window.SITE_TERMS = [{"id": "0001", "f": "H", "sub": "人工知能とは", "term": "AI効果", "desc": "AI で何かができるようになると、それは単なる自動化で知能ではない、と見なされてしまう現象。", "y": "aiこうか", "mt": "できると知能と見なされない", "my": "できるとちのうとみなされない"}, {"id": "0002", "f": "H", "sub": "人工知能とは", "term": "エージェント", "desc": "周りの環境を観察し、目的に向けて自分で行動を選ぶもの。AI の分野では、知的な行動をするプログラムやロボットを指す。", "y": "えーじぇんと", "mt": "環境を見て自分で行動を選ぶ", "my": "かんきょうをみてじぶんでこうどうをえらぶ"}, {"id": "0003", "f": "H", "sub": "人工知能とは", "term": "チューリングテスト", "desc": "アラン・チューリングが考えた、機械に知能があるかを判定する方法。人が文字だけで会話して、相手が機械か人か見分けられなければ、知能があるとみなす。", "y": "ちゅーりんぐてすと", "mt": "会話で機械の知能を判定", "my": "かいわできかいのちのうをはんてい"}, {"id": "0004", "f": "H", "sub": "人工知能とは", "term": "ローブナーコンテスト", "desc": "チューリングテストの考えをもとに、人と見分けがつかない会話プログラムを競うコンテスト。", "y": "ろーぶなーこんてすと", "mt": "人らしい会話プログラムを競う", "my": "ひとらしいかいわぷろぐらむをきそう"}, {"id": "0005", "f": "H", "sub": "人工知能とは", "term": "中国語の部屋", "desc": "ジョン・サールの思考実験。中国語がわからない人がマニュアルどおりに答えても、中国語を理解しているとはいえない。チューリングテストへの反論。", "y": "ちゅうごくごのへや", "mt": "答えられても理解とは限らない", "my": "こたえられてもりかいとはかぎらない"}, {"id": "0006", "f": "H", "sub": "人工知能とは", "term": "強いAIと弱いAI", "desc": "ジョン・サールの分け方。強いAIは本当に心や理解を持つ AI、弱いAIは人の知能の一部をまねて道具として役立つ AI。", "y": "つよいaiとよわいai", "mt": "心を持つAIと知能の一部をまねるAI", "my": "こころをもつaiとちのうのいちぶをまねるai"}, {"id": "0007", "f": "H", "sub": "人工知能とは", "term": "シンボルグラウンディング問題", "desc": "記号（言葉）と、それが指す現実の意味を、コンピュータが結びつけられないという問題。", "y": "しんぼるぐらうんでぃんぐもんだい", "mt": "記号と現実の意味を結べない", "my": "きごうとげんじつのいみをむすべない"}, {"id": "0008", "f": "H", "sub": "人工知能とは", "term": "フレーム問題", "desc": "今の作業に関係あることだけを選んで考えることが、AI には難しいという問題。関係のないことまで全部考えると、処理が終わらない。", "y": "ふれーむもんだい", "mt": "関係あることだけ選ぶのが難しい", "my": "かんけいあることだけえらぶのがむずかしい"}, {"id": "0009", "f": "H", "sub": "人工知能とは", "term": "身体性", "desc": "知能には、体を通して世界とやり取りする経験が必要だという考え。", "y": "しんたいせい", "mt": "体を通した経験が要るという考え", "my": "からだをとおしたけいけんがいるというかんがえ"}, {"id": "0010", "f": "H", "sub": "人工知能とは", "term": "知識獲得のボトルネック", "desc": "専門家の知識を、コンピュータが使える形に取り出して書き尽くすのが難しいという問題。エキスパートシステムの限界になった。", "y": "ちしきかくとくのぼとるねっく", "mt": "知識を書き尽くすのが難しい", "my": "ちしきをかきつくすのがむずかしい"}, {"id": "0011", "f": "H", "sub": "人工知能とは", "term": "トイ・プロブレム", "desc": "迷路やパズルのように、ルールとゴールがはっきりした、おもちゃのような問題。初期の AI はこれは解けたが、現実の問題は解けなかった。", "y": "といぷろぶれむ", "mt": "ルールがはっきりした問題", "my": "るーるがはっきりしたもんだい"}, {"id": "0012", "f": "H", "sub": "人工知能とは", "term": "シンギュラリティ", "desc": "AI が人間の知能を超え、社会が予測できないほど変わるとされる時点（技術的特異点）。2045年ごろとする説がある。", "y": "しんぎゅらりてぃ", "mt": "AIが人間の知能を超える時点", "my": "aiがにんげんのちのうをこえるじてん"}, {"id": "0013", "f": "H", "sub": "探索と知識", "term": "ダートマス会議", "desc": "1956年にアメリカで開かれた研究会。「人工知能」という言葉が使われ、AI 研究の始まりとされる。", "y": "だーとますかいぎ", "mt": "AI研究の始まりの研究会", "my": "aiけんきゅうのはじまりのけんきゅうかい"}, {"id": "0014", "f": "H", "sub": "探索と知識", "term": "探索木", "desc": "問題を解く途中の状態を、枝分かれする木の形で表したもの。探索で答えにたどり着く道を探す。", "y": "たんさくぎ", "mt": "途中の状態を木の形で表す", "my": "とちゅうのじょうたいをきのかたちであらわす"}, {"id": "0015", "f": "H", "sub": "探索と知識", "term": "幅優先探索と深さ優先探索", "desc": "幅優先探索は、近い所から順に広く調べる。深さ優先探索は、1つの道を行き止まりまで調べてから戻る。", "y": "はばゆうせんたんさくとふかさゆうせんたんさく", "mt": "広く調べるか深く調べるか", "my": "ひろくしらべるかふかくしらべるか"}, {"id": "0016", "f": "H", "sub": "探索と知識", "term": "ハノイの塔", "desc": "大きさの違う円盤を、決まりに従って別の棒に移すパズル。探索の例としてよく使われる。", "y": "はのいのとう", "mt": "円盤を別の棒に移すパズル", "my": "えんばんをべつのぼうにうつすぱずる"}, {"id": "0017", "f": "H", "sub": "探索と知識", "term": "STRIPS", "desc": "前提条件・行動・結果を書いて、目的を達成する行動の順番を考える、自動計画（プランニング）の方法。", "y": "strips", "mt": "行動の順番を考える自動計画", "my": "こうどうのじゅんばんをかんがえるじどうけいかく"}, {"id": "0018", "f": "H", "sub": "探索と知識", "term": "SHRDLU", "desc": "テリー・ウィノグラードが作った、積み木の世界を言葉の指示で動かすシステム。", "y": "shrdlu", "mt": "積み木の世界を言葉で動かす", "my": "つみきのせかいをことばでうごかす"}, {"id": "0019", "f": "H", "sub": "探索と知識", "term": "Mini-Max法", "desc": "ゲームで、相手は自分に最も不利な手を、自分は最も有利な手を選ぶと考えて、手を決める方法。", "y": "mini-maxほう", "mt": "相手は最も不利な手を選ぶと考える", "my": "あいてはもっともふりなてをえらぶとかんがえる"}, {"id": "0020", "f": "H", "sub": "探索と知識", "term": "αβ法", "desc": "Mini-Max法で、調べなくても結果が変わらない枝を省いて（枝刈り）、計算を減らす方法。", "y": "あるふぁべーたほう", "mt": "不要な枝を省いて計算を減らす", "my": "ふようなえだをはぶいてけいさんをへらす"}, {"id": "0021", "f": "H", "sub": "探索と知識", "term": "モンテカルロ法", "desc": "ランダムに何度も試して（ゲームなら最後までランダムに打って）、その結果から良い手を見積もる方法。", "y": "もんてかるろほう", "mt": "ランダムに何度も試して見積もる", "my": "らんだむになんどもためしてみつもる"}, {"id": "0022", "f": "H", "sub": "探索と知識", "term": "ブルートフォース", "desc": "考えられるすべての場合を、しらみつぶしに調べる方法。", "y": "ぶるーとふぉーす", "mt": "すべての場合を調べる", "my": "すべてのばあいをしらべる"}, {"id": "0023", "f": "H", "sub": "探索と知識", "term": "エキスパートシステム", "desc": "専門家の知識をルールとして入れ、専門家のように判断させるシステム。第二次AIブームの中心。", "y": "えきすぱーとしすてむ", "mt": "専門家の知識をルールで入れる", "my": "せんもんかのちしきをるーるでいれる"}, {"id": "0024", "f": "H", "sub": "探索と知識", "term": "MYCIN（マイシン）", "desc": "1970年代に作られた、血液の感染症を診断して抗生物質を勧めるエキスパートシステム。", "y": "mycin", "mt": "感染症を診断するシステム", "my": "かんせんしょうをしんだんするしすてむ"}, {"id": "0025", "f": "H", "sub": "探索と知識", "term": "DENDRAL", "desc": "1960年代に作られた、有機化合物の分子の構造を推定するエキスパートシステム。", "y": "dendral", "mt": "分子の構造を推定する", "my": "ぶんしのこうぞうをすいていする"}, {"id": "0026", "f": "H", "sub": "探索と知識", "term": "ELIZA（イライザ）", "desc": "1960年代の会話プログラム。決まったパターンで言葉を返すだけだが、人と話しているように感じさせた。", "y": "eliza", "mt": "パターンで言葉を返す会話", "my": "ぱたーんでことばをかえすかいわ"}, {"id": "0027", "f": "H", "sub": "探索と知識", "term": "意味ネットワーク", "desc": "概念を点、概念どうしの関係を線で結んで、知識を表す方法。is-a（〜の一種）や part-of（〜の一部）などの関係を使う。", "y": "いみねっとわーく", "mt": "概念を点と線で結ぶ", "my": "がいねんをてんとせんでむすぶ"}, {"id": "0028", "f": "H", "sub": "探索と知識", "term": "is-aの関係とpart-ofの関係", "desc": "知識表現で使う関係。is-a は「〜は〜の一種」（犬は動物）、part-of は「〜は〜の一部」（車輪は車の一部）。has-a は「〜を持つ」。", "y": "is-aのかんけいとpart-ofのかんけい", "mt": "一種の関係と一部の関係", "my": "いっしゅのかんけいといちぶのかんけい"}, {"id": "0029", "f": "H", "sub": "探索と知識", "term": "オントロジー", "desc": "ある分野の概念と、その関係を、決まった形で整理して書いたもの。知識を共有・再利用するために使う。", "y": "おんとろじー", "mt": "概念と関係を決まった形で整理", "my": "がいねんとかんけいをきまったかたちでせいり"}, {"id": "0030", "f": "H", "sub": "探索と知識", "term": "Cycプロジェクト", "desc": "人間の一般常識を、すべてコンピュータに入れようとした長期のプロジェクト。", "y": "cycぷろじぇくと", "mt": "一般常識をすべて入れる計画", "my": "いっぱんじょうしきをすべていれるけいかく"}, {"id": "0031", "f": "H", "sub": "探索と知識", "term": "セマンティックWeb", "desc": "Web の情報に意味を表すデータを付けて、コンピュータが意味を理解して処理できるようにする考え。", "y": "せまんてぃっくweb", "mt": "Webに意味のデータを付ける", "my": "webにいみのでーたをつける"}, {"id": "0032", "f": "H", "sub": "探索と知識", "term": "ワトソン", "desc": "IBM の質問応答システム。アメリカのクイズ番組で人間のチャンピオンに勝った。", "y": "わとそん", "mt": "クイズ番組で勝った質問応答", "my": "くいずばんぐみでかったしつもんおうとう"}, {"id": "0033", "f": "H", "sub": "探索と知識", "term": "東ロボくん", "desc": "東京大学の入学試験に合格できる AI を目指したプロジェクト。読解力などの課題が明らかになった。", "y": "とうろぼくん", "mt": "東大合格を目指したAI", "my": "とうだいごうかくをめざしたai"}, {"id": "0034", "f": "H", "sub": "機械学習とDLの歩み", "term": "次元の呪い", "desc": "データの特徴（次元）が増えると、学習に必要なデータの量が爆発的に増え、うまく学習できなくなること。", "y": "じげんののろい", "mt": "次元が増えるとデータが足りない", "my": "じげんがふえるとでーたがたりない"}, {"id": "0035", "f": "H", "sub": "機械学習とDLの歩み", "term": "統計的自然言語処理", "desc": "大量の文章のデータから、確率や統計を使って言葉を扱う方法。統計的機械翻訳もその1つ。", "y": "とうけいてきしぜんげんごしょり", "mt": "確率と統計で言葉を扱う", "my": "かくりつととうけいでことばをあつかう"}, {"id": "0036", "f": "H", "sub": "機械学習とDLの歩み", "term": "レコメンデーションエンジン", "desc": "利用者の好みや行動から、合いそうな商品などを勧める仕組み。機械学習の代表的な使い道。", "y": "れこめんでーしょんえんじん", "mt": "好みから合いそうな物を勧める", "my": "このみからあいそうなものをすすめる"}, {"id": "0037", "f": "H", "sub": "機械学習とDLの歩み", "term": "ネオコグニトロン", "desc": "福島邦彦が考えた、人の視覚の仕組みをまねたニューラルネットワーク。CNN の原形とされる。", "y": "ねおこぐにとろん", "mt": "視覚をまねたCNNの原形", "my": "しかくをまねたcnnのげんけい"}, {"id": "0038", "f": "H", "sub": "機械学習とDLの歩み", "term": "LeNet", "desc": "ヤン・ルカンらが作った、手書き数字を認識する初期の CNN。", "y": "lenet", "mt": "手書き数字を認識する初期のCNN", "my": "てがきすうじをにんしきするしょきのcnn"}, {"id": "0039", "f": "H", "sub": "機械学習とDLの歩み", "term": "ImageNetとILSVRC", "desc": "ImageNet は大規模な画像のデータセット。ILSVRC はそれを使った画像認識のコンテストで、2012年にディープラーニング（AlexNet）が大差で優勝した。", "y": "imagenetとilsvrc", "mt": "大規模な画像集とコンペ", "my": "だいきぼながぞうしゅうとこんぺ"}, {"id": "0040", "f": "H", "sub": "機械学習とDLの歩み", "term": "AlphaGo（アルファ碁）", "desc": "DeepMind が作った囲碁の AI。ディープラーニングと強化学習、モンテカルロ木探索を組み合わせ、トップ棋士に勝った。", "y": "alphago", "mt": "囲碁のAI", "my": "いごのai"}, {"id": "0041", "f": "M", "sub": "教師あり学習", "term": "線形回帰", "desc": "データの関係を直線（線形の式）で表して、数の値を予測する方法。説明に使う変数が1つなら単回帰分析、複数なら重回帰分析。", "y": "せんけいかいき", "mt": "直線の式で値を予測", "my": "ちょくせんのしきであたいをよそく"}, {"id": "0042", "f": "M", "sub": "教師あり学習", "term": "ロジスティック回帰", "desc": "名前は回帰だが、分類に使う方法。あるクラスに入る確率を、シグモイド関数で 0〜1 の値にして出す。", "y": "ろじすてぃっくかいき", "mt": "確率を出して分類する", "my": "かくりつをだしてぶんるいする"}, {"id": "0043", "f": "M", "sub": "教師あり学習", "term": "サポートベクターマシン（SVM）", "desc": "クラスの境界とデータの間の距離（マージン）を最大にする境界を見つける分類の方法。", "abbr": "Support Vector Machine", "y": "さぽーとべくたーましん", "mt": "マージンを最大にする境界", "my": "まーじんをさいだいにするきょうかい"}, {"id": "0044", "f": "M", "sub": "教師あり学習", "term": "カーネルトリック", "desc": "データを高い次元に移したときの計算を、実際に移さずに効率よく行う工夫。SVM で、まっすぐな線で分けられないデータを分けるのに使う。", "y": "かーねるとりっく", "mt": "高い次元の計算を効率よく", "my": "たかいじげんのけいさんをこうりつよく"}, {"id": "0045", "f": "M", "sub": "教師あり学習", "term": "決定木", "desc": "「はい・いいえ」の質問を木の形につなげて、分類や予測をする方法。判断の理由がわかりやすい。", "y": "けっていぎ", "mt": "質問を木の形につなげる", "my": "しつもんをきのかたちにつなげる"}, {"id": "0046", "f": "M", "sub": "教師あり学習", "term": "アンサンブル学習", "desc": "複数のモデルを組み合わせて、1つのモデルより良い予測をする方法。バギングやブースティングがある。", "y": "あんさんぶるがくしゅう", "mt": "複数のモデルを組み合わせる", "my": "ふくすうのもでるをくみあわせる"}, {"id": "0047", "f": "M", "sub": "教師あり学習", "term": "バギング", "desc": "データから重複を許して取り出した複数のデータ（ブートストラップサンプリング）で、別々にモデルを作り、結果をまとめる方法。", "y": "ばぎんぐ", "mt": "取り出したデータで別々に学ぶ", "my": "とりだしたでーたでべつべつにまなぶ"}, {"id": "0048", "f": "M", "sub": "教師あり学習", "term": "ランダムフォレスト", "desc": "バギングで作った多数の決定木に、使う特徴もランダムに選ばせて、多数決などで結果を出す方法。", "y": "らんだむふぉれすと", "mt": "多数の決定木で多数決", "my": "たすうのけっていぎでたすうけつ"}, {"id": "0049", "f": "M", "sub": "教師あり学習", "term": "ブースティング", "desc": "前のモデルが間違えたデータを重く見ながら、モデルを順番に作って組み合わせる方法。勾配ブースティングなど。", "y": "ぶーすてぃんぐ", "mt": "間違いを重く見て順に作る", "my": "まちがいをおもくみてじゅんにつくる"}, {"id": "0050", "f": "M", "sub": "教師あり学習", "term": "自己回帰モデル（ARモデル）", "desc": "過去の自分の値から、次の値を予測する時系列のモデル。複数の時系列を同時に扱うものはベクトル自己回帰モデル（VARモデル）。", "abbr": "Autoregressive Model", "y": "じこかいきもでる", "mt": "過去の値から次を予測", "my": "かこのあたいからつぎをよそく"}, {"id": "0051", "f": "M", "sub": "教師なし学習", "term": "k-means法", "desc": "データを、決めた k 個のグループに分けるクラスタリングの方法。各グループの中心とデータの距離をもとに分ける。", "y": "k-meansほう", "mt": "k個のグループに分ける", "my": "kこのぐるーぷにわける"}, {"id": "0052", "f": "M", "sub": "教師なし学習", "term": "ウォード法", "desc": "グループをまとめたときのばらつきの増え方が最も小さくなるように、少しずつまとめていく階層的なクラスタリングの方法。結果は樹形図（デンドログラム）で表す。", "y": "うぉーどほう", "mt": "ばらつきが最も増えないようにまとめる", "my": "ばらつきがもっともふえないようにまとめる"}, {"id": "0053", "f": "M", "sub": "教師なし学習", "term": "主成分分析（PCA）", "desc": "データのばらつきが大きい方向（主成分）を見つけて、少ない次元にまとめる次元削減の方法。", "abbr": "Principal Component Analysis", "y": "しゅせいぶんぶんせき", "mt": "ばらつきの大きい方向にまとめる", "my": "ばらつきのおおきいほうこうにまとめる"}, {"id": "0054", "f": "M", "sub": "教師なし学習", "term": "t-SNE", "desc": "高い次元のデータを、近いものは近いまま 2〜3 次元に移して、見える形にする次元削減の方法。", "y": "t-sne", "mt": "近いものを近いまま見える形に", "my": "ちかいものをちかいままみえるかたちに"}, {"id": "0055", "f": "M", "sub": "教師なし学習", "term": "特異値分解（SVD）", "desc": "行列を3つの行列の積に分ける計算。次元削減や推薦などに使う。", "abbr": "Singular Value Decomposition", "y": "とくいちぶんかい", "mt": "行列を3つの積に分ける", "my": "ぎょうれつを3つのせきにわける"}, {"id": "0056", "f": "M", "sub": "教師なし学習", "term": "多次元尺度構成法（MDS）", "desc": "データどうしの距離（似ていなさ）をなるべく保ったまま、低い次元に配置する方法。", "abbr": "Multi-Dimensional Scaling", "y": "たじげんしゃくどこうせいほう", "mt": "距離を保って低い次元に配置", "my": "きょりをたもってひくいじげんにはいち"}, {"id": "0057", "f": "M", "sub": "教師なし学習", "term": "トピックモデル", "desc": "文書が、どんな話題（トピック）からできているかを推定するモデル。代表は潜在的ディリクレ配分法（LDA）。", "y": "とぴっくもでる", "mt": "文書の話題を推定する", "my": "ぶんしょのわだいをすいていする"}, {"id": "0058", "f": "M", "sub": "教師なし学習", "term": "協調フィルタリング", "desc": "似た好みの利用者の行動をもとに、おすすめを決める方法。新しい利用者や商品にはデータがなく、勧めにくい（コールドスタート問題）。", "y": "きょうちょうふぃるたりんぐ", "mt": "似た利用者の行動で勧める", "my": "にたりようしゃのこうどうですすめる"}, {"id": "0059", "f": "M", "sub": "教師なし学習", "term": "コンテンツベースフィルタリング", "desc": "商品そのものの特徴と、利用者の好みの特徴を比べて、おすすめを決める方法。", "y": "こんてんつべーすふぃるたりんぐ", "mt": "商品の特徴と好みを比べる", "my": "しょうひんのとくちょうとこのみをくらべる"}, {"id": "0060", "f": "M", "sub": "強化学習", "term": "マルコフ決定過程", "desc": "次の状態が、今の状態と行動だけで決まると考えて、強化学習の問題を表す枠組み。", "y": "まるこふけっていかてい", "mt": "今の状態と行動で次が決まる", "my": "いまのじょうたいとこうどうでつぎがきまる"}, {"id": "0061", "f": "M", "sub": "強化学習", "term": "割引率", "desc": "強化学習で、先の報酬ほど価値を小さく見積もるための率。0〜1 の値。", "y": "わりびきりつ", "mt": "先の報酬ほど小さく見積もる", "my": "さきのほうしゅうほどちいさくみつもる"}, {"id": "0062", "f": "M", "sub": "強化学習", "term": "状態価値関数と行動価値関数", "desc": "状態価値関数は、ある状態がどれだけ良いか。行動価値関数（Q値）は、ある状態である行動をとることがどれだけ良いか。", "y": "じょうたいかちかんすうとこうどうかちかんすう", "mt": "状態の良さと行動の良さ", "my": "じょうたいのよさとこうどうのよさ"}, {"id": "0063", "f": "M", "sub": "強化学習", "term": "Q学習", "desc": "行動価値（Q値）を、次の状態で最も良い行動の価値を使って更新していく強化学習の方法。", "y": "qがくしゅう", "mt": "最も良い行動の価値で更新", "my": "もっともよいこうどうのかちでこうしん"}, {"id": "0064", "f": "M", "sub": "強化学習", "term": "SARSA", "desc": "行動価値を、次の状態で実際に選んだ行動の価値を使って更新する強化学習の方法。", "y": "sarsa", "mt": "実際に選んだ行動の価値で更新", "my": "じっさいにえらんだこうどうのかちでこうしん"}, {"id": "0065", "f": "M", "sub": "強化学習", "term": "ε-greedy方策", "desc": "ふだんは今いちばん良い行動を選び、確率 ε でランダムな行動を試す方法。活用と探索のバランスをとる。", "y": "いぷしろん-greedyほうさく", "mt": "たまにランダムな行動を試す", "my": "たまにらんだむなこうどうをためす"}, {"id": "0066", "f": "M", "sub": "強化学習", "term": "バンディットアルゴリズム", "desc": "どの選択肢が良いかわからない中で、試す（探索）と良いものを使う（活用）のバランスをとる方法。UCB方策など。", "y": "ばんでぃっとあるごりずむ", "mt": "探索と活用のバランスをとる", "my": "たんさくとかつようのばらんすをとる"}, {"id": "0067", "f": "M", "sub": "強化学習", "term": "方策勾配法", "desc": "行動の選び方（方策）そのものを、報酬が増える方向に直接学習する方法。REINFORCE など。", "y": "ほうさくこうばいほう", "mt": "方策を直接学習する", "my": "ほうさくをちょくせつがくしゅうする"}, {"id": "0068", "f": "M", "sub": "強化学習", "term": "Actor-Critic", "desc": "行動を選ぶ Actor と、その行動を評価する Critic の2つを組み合わせて学ぶ強化学習の方法。", "y": "actor-critic", "mt": "行動を選ぶ役と評価する役", "my": "こうどうをえらぶやくとひょうかするやく"}, {"id": "0069", "f": "M", "sub": "モデルの評価", "term": "混同行列", "desc": "分類の結果を、真陽性・偽陽性・偽陰性・真陰性の4つに分けて数えた表。", "y": "こんどうぎょうれつ", "mt": "分類の結果を4つに分けた表", "my": "ぶんるいのけっかを4つにわけたひょう"}, {"id": "0070", "f": "M", "sub": "モデルの評価", "term": "偽陽性と偽陰性", "desc": "偽陽性は、本当は陰性なのに陽性と予測した誤り。偽陰性は、本当は陽性なのに陰性と予測した誤り。", "y": "ぎようせいとぎいんせい", "mt": "誤って陽性と誤って陰性", "my": "あやまってようせいとあやまっていんせい"}, {"id": "0071", "f": "M", "sub": "モデルの評価", "term": "適合率", "desc": "陽性と予測したもののうち、本当に陽性だった割合。誤って陽性と言うのを避けたいときに大事。", "y": "てきごうりつ", "mt": "陽性の予測のうち本当に陽性", "my": "ようせいのよそくのうちほんとうにようせい"}, {"id": "0072", "f": "M", "sub": "モデルの評価", "term": "再現率", "desc": "本当に陽性のもののうち、陽性と予測できた割合。見逃しを避けたいときに大事。", "y": "さいげんりつ", "mt": "本当の陽性のうち当てた割合", "my": "ほんとうのようせいのうちあてたわりあい"}, {"id": "0073", "f": "M", "sub": "モデルの評価", "term": "F値", "desc": "適合率と再現率の調和平均。2つのバランスを1つの数で見る。", "y": "fち", "mt": "適合率と再現率の調和平均", "my": "てきごうりつとさいげんりつのちょうわへいきん"}, {"id": "0074", "f": "M", "sub": "モデルの評価", "term": "ROC曲線とAUC", "desc": "ROC曲線は、判定のしきい値を変えたときの、偽陽性率と真陽性率の関係のグラフ。AUC はその下の面積で、1 に近いほど良い。", "y": "rocきょくせんとauc", "mt": "しきい値を変えたときのグラフ", "my": "しきいちをかえたときのぐらふ"}, {"id": "0075", "f": "M", "sub": "モデルの評価", "term": "平均二乗誤差（MSE）", "desc": "予測と正解の差を2乗して平均したもの。その平方根が二乗平均平方根誤差（RMSE）、差の絶対値の平均が平均絶対値誤差（MAE）。", "abbr": "Mean Squared Error", "y": "へいきんにじょうごさ", "mt": "差を2乗して平均したもの", "my": "さを2じょうしてへいきんしたもの"}, {"id": "0076", "f": "M", "sub": "モデルの評価", "term": "ホールドアウト検証", "desc": "データを学習用とテスト用に1回分けて、テスト用で性能を確かめる方法。", "y": "ほーるどあうとけんしょう", "mt": "学習用とテスト用に1回分ける", "my": "がくしゅうようとてすとように1かいわける"}, {"id": "0077", "f": "M", "sub": "モデルの評価", "term": "k-分割交差検証", "desc": "データを k 個に分け、1つをテスト用、残りを学習用にする組み合わせを k 回くり返して、性能を平均する方法。", "y": "k-ぶんかつこうさけんしょう", "mt": "k回くり返して性能を確かめる", "my": "kかいくりかえしてせいのうをたしかめる"}, {"id": "0078", "f": "M", "sub": "モデルの評価", "term": "AICとBIC", "desc": "赤池情報量規準（AIC）とベイズ情報量規準（BIC）。モデルの当てはまりの良さと複雑さのバランスで、モデルを選ぶための指標。", "y": "aicとbic", "mt": "当てはまりと複雑さのバランス", "my": "あてはまりとふくざつさのばらんす"}, {"id": "0079", "f": "M", "sub": "モデルの評価", "term": "オッカムの剃刀", "desc": "同じくらい説明できるなら、より単純なものを選ぶべきという考え。モデルを選ぶときの指針。", "y": "おっかむのかみそり", "mt": "単純なものを選ぶべき", "my": "たんじゅんなものをえらぶべき"}, {"id": "0080", "f": "D", "sub": "ニューラルネットワーク", "term": "単純パーセプトロン", "desc": "入力層と出力層だけの、いちばん単純なニューラルネットワーク。まっすぐな線で分けられる問題しか解けない。", "y": "たんじゅんぱーせぷとろん", "mt": "入力層と出力層だけ", "my": "にゅうりょくそうとしゅつりょくそうだけ"}, {"id": "0081", "f": "D", "sub": "ニューラルネットワーク", "term": "多層パーセプトロン", "desc": "入力層と出力層の間に隠れ層を入れたニューラルネットワーク。複雑な問題を解ける。", "y": "たそうぱーせぷとろん", "mt": "隠れ層を入れたネットワーク", "my": "かくれそうをいれたねっとわーく"}, {"id": "0082", "f": "D", "sub": "ニューラルネットワーク", "term": "GPU", "desc": "画像処理用の演算装置。同じ計算を大量に並列で行うのが得意で、ディープラーニングの学習に向く。", "abbr": "Graphics Processing Unit", "y": "gpu", "mt": "並列の計算が得意な装置", "my": "へいれつのけいさんがとくいなそうち"}, {"id": "0083", "f": "D", "sub": "ニューラルネットワーク", "term": "TPU", "desc": "Google が作った、ディープラーニングの計算に特化した演算装置。", "abbr": "Tensor Processing Unit", "y": "tpu", "mt": "深層学習に特化した装置", "my": "しんそうがくしゅうにとっかしたそうち"}, {"id": "0084", "f": "D", "sub": "活性化関数", "term": "シグモイド関数", "desc": "入力を 0〜1 の値に変える活性化関数。微分の最大値が小さく、層が深いと勾配消失が起きやすい。", "y": "しぐもいどかんすう", "mt": "0から1の値に変える", "my": "0から1のあたいにかえる"}, {"id": "0085", "f": "D", "sub": "活性化関数", "term": "tanh関数", "desc": "入力を −1〜1 の値に変える活性化関数。シグモイド関数より勾配が消えにくい。", "y": "tanhかんすう", "mt": "-1から1の値に変える", "my": "-1から1のあたいにかえる"}, {"id": "0086", "f": "D", "sub": "活性化関数", "term": "ReLU関数", "desc": "入力が 0 以下なら 0、正ならそのまま出す活性化関数。勾配が消えにくく、よく使われる。", "y": "reluかんすう", "mt": "0以下は0で正はそのまま", "my": "0いかは0でせいはそのまま"}, {"id": "0087", "f": "D", "sub": "活性化関数", "term": "Leaky ReLU関数", "desc": "ReLU関数の、入力が 0 以下のときにも少しだけ傾きを持たせたもの。", "y": "leakyreluかんすう", "mt": "0以下にも少し傾きを持つ", "my": "0いかにもすこしかたむきをもつ"}, {"id": "0088", "f": "D", "sub": "活性化関数", "term": "ソフトマックス関数", "desc": "複数の出力を、合計が 1 になる確率に変える関数。多クラス分類の出力層で使う。", "y": "そふとまっくすかんすう", "mt": "合計が1の確率に変える", "my": "ごうけいが1のかくりつにかえる"}, {"id": "0089", "f": "D", "sub": "誤差関数と正則化", "term": "交差エントロピー", "desc": "予測の確率分布と正解の分布のずれを表す誤差関数。分類でよく使う。", "y": "こうさえんとろぴー", "mt": "分布のずれを表す誤差関数", "my": "ぶんぷのずれをあらわすごさかんすう"}, {"id": "0090", "f": "D", "sub": "誤差関数と正則化", "term": "KLダイバージェンス", "desc": "カルバック・ライブラー情報量。2つの確率分布がどれだけ違うかを表す量。", "y": "klだいばーじぇんす", "mt": "2つの分布の違いを表す", "my": "2つのぶんぷのちがいをあらわす"}, {"id": "0091", "f": "D", "sub": "誤差関数と正則化", "term": "Contrastive LossとTriplet Loss", "desc": "データどうしの距離を学ぶための誤差関数。似たものは近く、違うものは遠くなるように学習する。", "y": "contrastivelossとtripletloss", "mt": "似たものを近くに学ぶ", "my": "にたものをちかくにまなぶ"}, {"id": "0092", "f": "D", "sub": "誤差関数と正則化", "term": "L1正則化", "desc": "重みの絶対値の合計を罰として加える正則化。不要な重みが 0 になりやすい。線形回帰に使うとラッソ回帰。", "y": "l1せいそくか", "mt": "不要な重みが0になりやすい", "my": "ふようなおもみが0になりやすい"}, {"id": "0093", "f": "D", "sub": "誤差関数と正則化", "term": "L2正則化", "desc": "重みの2乗の合計を罰として加える正則化。重みが全体に小さくなる。線形回帰に使うとリッジ回帰。", "y": "l2せいそくか", "mt": "重みが全体に小さくなる", "my": "おもみがぜんたいにちいさくなる"}, {"id": "0094", "f": "D", "sub": "誤差関数と正則化", "term": "連鎖律", "desc": "合成関数の微分は、それぞれの微分の掛け算で求められるという法則。誤差逆伝播法の土台。", "y": "れんさりつ", "mt": "合成関数の微分は掛け算", "my": "ごうせいかんすうのびぶんはかけざん"}, {"id": "0095", "f": "D", "sub": "誤差関数と正則化", "term": "信用割当問題", "desc": "結果に対して、どの重みがどれだけ責任があるかを決める問題。誤差逆伝播法で解決した。", "y": "しんようわりあてもんだい", "mt": "どの重みに責任があるか", "my": "どのおもみにせきにんがあるか"}, {"id": "0096", "f": "D", "sub": "最適化", "term": "確率的勾配降下法（SGD）", "desc": "データを1つずつ、またはランダムに選んだ一部で勾配を計算して、重みを更新する方法。", "abbr": "Stochastic Gradient Descent", "y": "かくりつてきこうばいこうかほう", "mt": "一部のデータで勾配を計算", "my": "いちぶのでーたでこうばいをけいさん"}, {"id": "0097", "f": "D", "sub": "最適化", "term": "学習率", "desc": "勾配降下法で、1回にどれだけ重みを動かすかを決める値。大きすぎると発散し、小さすぎると学習が遅い。", "y": "がくしゅうりつ", "mt": "1回に重みを動かす量", "my": "1かいにおもみをうごかすりょう"}, {"id": "0098", "f": "D", "sub": "最適化", "term": "エポックとイテレーション", "desc": "エポックは、学習データ全体を1回使い終わること。イテレーションは、重みを1回更新すること。", "y": "えぽっくといてれーしょん", "mt": "全体を1回使うことと1回の更新", "my": "ぜんたいを1かいつかうことと1かいのこうしん"}, {"id": "0099", "f": "D", "sub": "最適化", "term": "バッチ学習とミニバッチ学習とオンライン学習", "desc": "重みを更新するのに使うデータの量の違い。全部を使うのがバッチ、一部ずつがミニバッチ、1つずつがオンライン学習。", "y": "ばっちがくしゅうとみにばっちがくしゅうとおんらいんがくしゅう", "mt": "更新に使うデータの量の違い", "my": "こうしんにつかうでーたのりょうのちがい"}, {"id": "0100", "f": "D", "sub": "最適化", "term": "局所最適解と大域最適解", "desc": "局所最適解は、その周りでは最も良いが全体では最良でない解。大域最適解は、全体で最も良い解。", "y": "きょくしょさいてきかいとたいいきさいてきかい", "mt": "周りで最良と全体で最良", "my": "まわりでさいりょうとぜんたいでさいりょう"}, {"id": "0101", "f": "D", "sub": "最適化", "term": "鞍点", "desc": "ある方向から見ると最小、別の方向から見ると最大になっている点。学習が止まりやすい。", "y": "あんてん", "mt": "方向で最小にも最大にもなる点", "my": "ほうこうでさいしょうにもさいだいにもなるてん"}, {"id": "0102", "f": "D", "sub": "最適化", "term": "モーメンタム", "desc": "前の更新の勢いを引き継いで重みを動かす方法。谷を速く進み、振動を抑える。", "y": "もーめんたむ", "mt": "前の更新の勢いを引き継ぐ", "my": "まえのこうしんのいきおいをひきつぐ"}, {"id": "0103", "f": "D", "sub": "最適化", "term": "AdaGrad", "desc": "よく更新された重みほど学習率を小さくしていく最適化の方法。学習が進むと更新がほとんど止まる弱点がある。", "y": "adagrad", "mt": "よく更新した重みの学習率を下げる", "my": "よくこうしんしたおもみのがくしゅうりつをさげる"}, {"id": "0104", "f": "D", "sub": "最適化", "term": "RMSprop", "desc": "AdaGrad の、学習率が小さくなりすぎる弱点を、最近の勾配を重く見ることで改良した方法。AdaDelta も同じ目的の改良。", "y": "rmsprop", "mt": "最近の勾配を重く見る", "my": "さいきんのこうばいをおもくみる"}, {"id": "0105", "f": "D", "sub": "最適化", "term": "Adam", "desc": "モーメンタムと RMSprop の考えを合わせた最適化の方法。よく使われる。AdaBound や AMSBound は、その改良版。", "y": "adam", "mt": "モーメンタムとRMSpropを合わせる", "my": "もーめんたむとrmspropをあわせる"}, {"id": "0106", "f": "D", "sub": "最適化", "term": "早期終了", "desc": "検証用のデータでの誤差が増え始めたら学習を止めて、過学習を防ぐ方法（アーリーストッピング）。", "y": "そうきしゅうりょう", "mt": "誤差が増え始めたら止める", "my": "ごさがふえはじめたらとめる"}, {"id": "0107", "f": "D", "sub": "最適化", "term": "二重降下現象", "desc": "モデルを大きくしていくと、テストの誤差がいったん下がり、上がり、また下がる現象。", "y": "にじゅうこうかげんしょう", "mt": "誤差が下がり上がりまた下がる", "my": "ごさがさがりあがりまたさがる"}, {"id": "0108", "f": "D", "sub": "最適化", "term": "ハイパーパラメータ", "desc": "学習率や層の数など、学習の前に人が決める値。グリッドサーチやランダムサーチで良い値を探す。", "y": "はいぱーぱらめーた", "mt": "学習の前に人が決める値", "my": "がくしゅうのまえにひとがきめるあたい"}, {"id": "0109", "f": "D", "sub": "層と構造", "term": "全結合層", "desc": "前の層のすべてのニューロンと、次の層のすべてのニューロンがつながった層。", "y": "ぜんけつごうそう", "mt": "すべてのニューロンがつながる", "my": "すべてのにゅーろんがつながる"}, {"id": "0110", "f": "D", "sub": "層と構造", "term": "畳み込み層", "desc": "フィルタ（カーネル）を画像の上でずらしながら掛け合わせて、特徴（特徴マップ）を取り出す層。", "y": "たたみこみそう", "mt": "フィルタで特徴を取り出す", "my": "ふぃるたでとくちょうをとりだす"}, {"id": "0111", "f": "D", "sub": "層と構造", "term": "ストライドとパディング", "desc": "ストライドはフィルタをずらす幅。パディングは、画像の周りに値を足して、端の情報も扱えるようにすること。", "y": "すとらいどとぱでぃんぐ", "mt": "ずらす幅と周りに足す値", "my": "ずらすはばとまわりにたすあたい"}, {"id": "0112", "f": "D", "sub": "層と構造", "term": "Dilated Convolution", "desc": "フィルタの要素の間をあけて、少ない計算で広い範囲を見る畳み込み。Atrous Convolution とも呼ぶ。", "y": "dilatedconvolution", "mt": "間をあけて広い範囲を見る", "my": "あいだをあけてひろいはんいをみる"}, {"id": "0113", "f": "D", "sub": "層と構造", "term": "Depthwise Separable Convolution", "desc": "畳み込みを、チャネルごとの畳み込みと、1×1 の畳み込みに分けて、計算を大きく減らす方法。", "y": "depthwiseseparableconvolution", "mt": "畳み込みを分けて計算を減らす", "my": "たたみこみをわけてけいさんをへらす"}, {"id": "0114", "f": "D", "sub": "層と構造", "term": "プーリング層", "desc": "決まった範囲の最大値（最大値プーリング）や平均（平均値プーリング）をとって、特徴マップを小さくする層。位置の少しのずれに強くなる（不変性の獲得）。", "y": "ぷーりんぐそう", "mt": "最大や平均で小さくする", "my": "さいだいやへいきんでちいさくする"}, {"id": "0115", "f": "D", "sub": "層と構造", "term": "グローバルアベレージプーリング（GAP）", "desc": "特徴マップ全体の平均を1つの値にするプーリング。全結合層の代わりに使い、パラメータを減らせる。", "abbr": "Global Average Pooling", "y": "ぐろーばるあべれーじぷーりんぐ", "mt": "全体の平均を1つの値に", "my": "ぜんたいのへいきんを1つのあたいに"}, {"id": "0116", "f": "D", "sub": "層と構造", "term": "バッチ正規化", "desc": "ミニバッチごとに、各層の値を平均 0・分散 1 に整える方法。学習が安定して速くなる。", "y": "ばっちせいきか", "mt": "ミニバッチごとに値を整える", "my": "みにばっちごとにあたいをととのえる"}, {"id": "0117", "f": "D", "sub": "層と構造", "term": "レイヤー正規化", "desc": "1つのデータの中で、層の値をまとめて整える正規化。Transformer で使われる。ほかにインスタンス正規化やグループ正規化がある。", "y": "れいやーせいきか", "mt": "1つのデータの中で整える", "my": "1つのでーたのなかでととのえる"}, {"id": "0118", "f": "D", "sub": "層と構造", "term": "スキップ結合", "desc": "層を飛ばして、前の層の出力を後ろの層に足す結合。層を深くしても学習しやすくなる。ResNet で使われた。", "y": "すきっぷけつごう", "mt": "層を飛ばして出力を足す", "my": "そうをとばしてしゅつりょくをたす"}, {"id": "0119", "f": "D", "sub": "層と構造", "term": "リカレントニューラルネットワーク（RNN）", "desc": "前の時点の情報を次に引き継ぐ回帰結合層を持つネットワーク。時系列データや文章を扱う。", "abbr": "Recurrent Neural Network", "y": "りかれんとにゅーらるねっとわーく", "mt": "前の時点の情報を引き継ぐ", "my": "まえのじてんのじょうほうをひきつぐ"}, {"id": "0120", "f": "D", "sub": "層と構造", "term": "BPTT", "desc": "RNN を時間の方向に展開して、誤差逆伝播法で学習する方法。", "abbr": "Backpropagation Through Time", "y": "bptt", "mt": "時間の方向に展開して学習", "my": "じかんのほうこうにてんかいしてがくしゅう"}, {"id": "0121", "f": "D", "sub": "層と構造", "term": "エルマンネットワークとジョルダンネットワーク", "desc": "初期の RNN。エルマンネットワークは隠れ層の出力を、ジョルダンネットワークは出力層の出力を、次の時点の入力に戻す。", "y": "えるまんねっとわーくとじょるだんねっとわーく", "mt": "初期のRNN", "my": "しょきのrnn"}, {"id": "0122", "f": "D", "sub": "層と構造", "term": "LSTM", "desc": "ゲート機構と記憶セル（CEC）で、長い時系列でも大事な情報を覚えておけるようにした RNN。", "abbr": "Long Short-Term Memory", "y": "lstm", "mt": "ゲートで長い情報を覚える", "my": "げーとでながいじょうほうをおぼえる"}, {"id": "0123", "f": "D", "sub": "層と構造", "term": "GRU", "desc": "LSTM を簡単にした RNN。リセットゲートと更新ゲートの2つで情報を調整する。", "abbr": "Gated Recurrent Unit", "y": "gru", "mt": "LSTMを簡単にしたRNN", "my": "lstmをかんたんにしたrnn"}, {"id": "0124", "f": "D", "sub": "層と構造", "term": "双方向RNN", "desc": "過去から未来と、未来から過去の両方向に情報を流す RNN。文の前後の両方を使える。", "abbr": "Bidirectional RNN", "y": "そうほうこうrnn", "mt": "両方向に情報を流す", "my": "りょうほうこうにじょうほうをながす"}, {"id": "0125", "f": "D", "sub": "層と構造", "term": "教師強制", "desc": "RNN の学習で、前の時点の予測ではなく、正解を次の入力に使う方法。", "y": "きょうしきょうせい", "mt": "正解を次の入力に使う", "my": "せいかいをつぎのにゅうりょくにつかう"}, {"id": "0126", "f": "D", "sub": "Attentionと生成モデル", "term": "Seq2Seq", "desc": "エンコーダで入力の系列を読み込み、デコーダで出力の系列を作るモデル。機械翻訳などに使う。", "y": "seq2seq", "mt": "系列を読んで系列を作る", "my": "けいれつをよんでけいれつをつくる"}, {"id": "0127", "f": "D", "sub": "Attentionと生成モデル", "term": "Attention", "desc": "入力のどこに注目すればよいかを重み付けする仕組み。長い系列でも、必要な情報を取り出せる。", "y": "attention", "mt": "どこに注目するかを重み付け", "my": "どこにちゅうもくするかをおもみづけ"}, {"id": "0128", "f": "D", "sub": "Attentionと生成モデル", "term": "Self-Attention", "desc": "同じ系列の中の、各要素どうしの関係を計算する Attention。クエリ・キー・バリューを使う。", "y": "self-attention", "mt": "同じ系列の中の関係を計算", "my": "おなじけいれつのなかのかんけいをけいさん"}, {"id": "0129", "f": "D", "sub": "Attentionと生成モデル", "term": "Source-Target Attention", "desc": "デコーダの側から、エンコーダの出力のどこに注目するかを計算する Attention。", "y": "source-targetattention", "mt": "デコーダからエンコーダに注目", "my": "でこーだからえんこーだにちゅうもく"}, {"id": "0130", "f": "D", "sub": "Attentionと生成モデル", "term": "Multi-Head Attention", "desc": "Attention を複数（ヘッド）並べて、いろいろな関係を同時にとらえる仕組み。", "y": "multi-headattention", "mt": "複数並べて関係をとらえる", "my": "ふくすうならべてかんけいをとらえる"}, {"id": "0131", "f": "D", "sub": "Attentionと生成モデル", "term": "Transformer", "desc": "RNN を使わず、Attention だけで系列を処理するモデル。並列に計算でき、今の大規模言語モデルの土台。", "y": "transformer", "mt": "Attentionだけで系列を処理", "my": "attentionだけでけいれつをしょり"}, {"id": "0132", "f": "D", "sub": "Attentionと生成モデル", "term": "位置エンコーディング", "desc": "Transformer に、単語の順番の情報を与えるために、入力に足す値。", "y": "いちえんこーでぃんぐ", "mt": "単語の順番の情報を足す", "my": "たんごのじゅんばんのじょうほうをたす"}, {"id": "0133", "f": "D", "sub": "Attentionと生成モデル", "term": "オートエンコーダ", "desc": "入力を小さく縮め（エンコーダ）、元に戻す（デコーダ）ように学ぶネットワーク。次元削減や事前学習に使う。重ねたものは積層オートエンコーダ。", "y": "おーとえんこーだ", "mt": "縮めて元に戻すように学ぶ", "my": "ちぢめてもとにもどすようにまなぶ"}, {"id": "0134", "f": "D", "sub": "Attentionと生成モデル", "term": "変分オートエンコーダ（VAE）", "desc": "潜在変数を確率分布として学ぶオートエンコーダ。新しいデータを生成できる。VQ-VAE・info VAE・β-VAE などの改良版がある。", "abbr": "Variational Autoencoder", "y": "へんぶんおーとえんこーだ", "mt": "潜在変数を確率分布で学ぶ", "my": "せんざいへんすうをかくりつぶんぷでまなぶ"}, {"id": "0135", "f": "D", "sub": "データ拡張", "term": "データ拡張", "desc": "学習データに、反転・回転・切り抜きなどの変形を加えて、データの量と多様さを増やす方法。過学習を防ぐ。", "y": "でーたかくちょう", "mt": "変形を加えてデータを増やす", "my": "へんけいをくわえてでーたをふやす"}, {"id": "0136", "f": "D", "sub": "データ拡張", "term": "Cutout と Random Erasing", "desc": "画像の一部を四角く隠して（消して）学習させるデータ拡張。一部が見えなくても認識できるようになる。", "y": "cutoutとrandomerasing", "mt": "画像の一部を隠して学ぶ", "my": "がぞうのいちぶをかくしてまなぶ"}, {"id": "0137", "f": "D", "sub": "データ拡張", "term": "Mixup", "desc": "2枚の画像とそのラベルを、決めた割合で混ぜ合わせるデータ拡張。", "y": "mixup", "mt": "2枚の画像を混ぜ合わせる", "my": "2まいのがぞうをまぜあわせる"}, {"id": "0138", "f": "D", "sub": "データ拡張", "term": "CutMix", "desc": "画像の一部を別の画像で置き換え、ラベルも面積の割合で混ぜるデータ拡張。", "y": "cutmix", "mt": "一部を別の画像で置き換える", "my": "いちぶをべつのがぞうでおきかえる"}, {"id": "0139", "f": "D", "sub": "データ拡張", "term": "RandAugment", "desc": "たくさんの変形の中からランダムに選んで加えるデータ拡張。調整する値が少なくて済む。", "y": "randaugment", "mt": "ランダムに選んだ変形を加える", "my": "らんだむにえらんだへんけいをくわえる"}, {"id": "0140", "f": "D", "sub": "データ拡張", "term": "noisingとparaphrasing", "desc": "文章のデータ拡張。noising は単語を消す・入れ替えるなどのノイズを加える。paraphrasing は意味を変えずに言い換える。", "y": "noisingとparaphrasing", "mt": "文章のデータ拡張", "my": "ぶんしょうのでーたかくちょう"}, {"id": "0141", "f": "X", "sub": "画像認識", "term": "AlexNet", "desc": "2012年の ILSVRC で優勝した CNN。ReLU やドロップアウトを使い、ディープラーニングの流行のきっかけになった。", "y": "alexnet", "mt": "2012年に優勝したCNN", "my": "2012ねんにゆうしょうしたcnn"}, {"id": "0142", "f": "X", "sub": "画像認識", "term": "VGG", "desc": "小さい 3×3 のフィルタを重ねて層を深くした CNN。", "y": "vgg", "mt": "小さいフィルタを重ねたCNN", "my": "ちいさいふぃるたをかさねたcnn"}, {"id": "0143", "f": "X", "sub": "画像認識", "term": "GoogLeNet", "desc": "大きさの違うフィルタを並列に使う Inception モジュールを重ねた CNN。", "y": "googlenet", "mt": "Inceptionモジュールを重ねる", "my": "inceptionもじゅーるをかさねる"}, {"id": "0144", "f": "X", "sub": "画像認識", "term": "ResNet", "desc": "スキップ結合で、100層を超えるとても深い CNN の学習を可能にしたモデル。", "y": "resnet", "mt": "スキップ結合でとても深いCNN", "my": "すきっぷけつごうでとてもふかいcnn"}, {"id": "0145", "f": "X", "sub": "画像認識", "term": "DenseNet", "desc": "各層に、それより前のすべての層の出力をつなぐ CNN。", "y": "densenet", "mt": "前のすべての層の出力をつなぐ", "my": "まえのすべてのそうのしゅつりょくをつなぐ"}, {"id": "0146", "f": "X", "sub": "画像認識", "term": "SENet", "desc": "チャネルごとの重要度を学んで、特徴に重み付けする仕組み（Squeeze-and-Excitation）を持つ CNN。", "y": "senet", "mt": "チャネルの重要度で重み付け", "my": "ちゃねるのじゅうようどでおもみづけ"}, {"id": "0147", "f": "X", "sub": "画像認識", "term": "EfficientNet", "desc": "ネットワークの深さ・幅・入力の解像度を、バランスよくまとめて大きくする方法で、少ない計算で高い精度を出したモデル。", "y": "efficientnet", "mt": "深さと幅と解像度をバランスよく", "my": "ふかさとはばとかいぞうどをばらんすよく"}, {"id": "0148", "f": "X", "sub": "画像認識", "term": "MobileNet", "desc": "Depthwise Separable Convolution で計算を減らした、スマホなどで動かすための軽い CNN。", "y": "mobilenet", "mt": "計算を減らしたスマホ向け", "my": "けいさんをへらしたすまほむけ"}, {"id": "0149", "f": "X", "sub": "画像認識", "term": "NAS（ニューラルアーキテクチャサーチ）", "desc": "ネットワークの構造そのものを、自動で探して決める方法。MnasNet はこれで作ったモバイル向けのモデル。", "abbr": "Neural Architecture Search", "y": "nas", "mt": "構造を自動で探す", "my": "こうぞうをじどうでさがす"}, {"id": "0150", "f": "X", "sub": "画像認識", "term": "Vision Transformer", "desc": "画像を小さな区画（パッチ）に分けて並べ、Transformer で処理する画像認識のモデル。", "y": "visiontransformer", "mt": "画像をパッチにしてTransformerで", "my": "がぞうをぱっちにしてtransformerで"}, {"id": "0151", "f": "X", "sub": "画像認識", "term": "物体検出", "desc": "画像の中の物の種類と、その位置（四角い枠）を見つけるタスク。", "y": "ぶったいけんしゅつ", "mt": "物の種類と位置を見つける", "my": "もののしゅるいといちをみつける"}, {"id": "0152", "f": "X", "sub": "画像認識", "term": "Faster R-CNN", "desc": "物の候補の場所を探す仕組み（RPN）もネットワークに入れて、速くした物体検出のモデル。R-CNN・Fast R-CNN の改良版。", "y": "fasterr-cnn", "mt": "候補の場所の探索も入れて速く", "my": "こうほのばしょのたんさくもいれてはやく"}, {"id": "0153", "f": "X", "sub": "画像認識", "term": "YOLO", "desc": "画像を1回見るだけで、物の位置と種類を同時に予測する、速い物体検出のモデル。", "y": "yolo", "mt": "1回見るだけで位置と種類", "my": "1かいみるだけでいちとしゅるい"}, {"id": "0154", "f": "X", "sub": "画像認識", "term": "SSD", "desc": "大きさの違う複数の特徴マップを使って、1回の処理で物体を検出するモデル。", "abbr": "Single Shot MultiBox Detector", "y": "ssd", "mt": "複数の特徴マップで1回で検出", "my": "ふくすうのとくちょうまっぷで1かいでけんしゅつ"}, {"id": "0155", "f": "X", "sub": "画像認識", "term": "FPN", "desc": "大きさの違う特徴マップを組み合わせて、大小さまざまな物を検出しやすくする仕組み。", "abbr": "Feature Pyramid Network", "y": "fpn", "mt": "大小の特徴マップを組み合わせる", "my": "だいしょうのとくちょうまっぷをくみあわせる"}, {"id": "0156", "f": "X", "sub": "画像認識", "term": "セマンティックセグメンテーション", "desc": "画像の1つ1つの画素が、どの種類の物かを分けるタスク。同じ種類の物は区別しない。", "y": "せまんてぃっくせぐめんてーしょん", "mt": "画素ごとに種類を分ける", "my": "がそごとにしゅるいをわける"}, {"id": "0157", "f": "X", "sub": "画像認識", "term": "インスタンスセグメンテーション", "desc": "物体ごとに画素の範囲を分けるタスク。同じ種類でも1つずつ区別する。両方を合わせたものがパノプティックセグメンテーション。", "y": "いんすたんすせぐめんてーしょん", "mt": "物体ごとに画素を分ける", "my": "ぶったいごとにがそをわける"}, {"id": "0158", "f": "X", "sub": "画像認識", "term": "FCN", "desc": "全結合層を使わず、すべて畳み込み層で作った、画素ごとに分類するセグメンテーションのモデル。", "abbr": "Fully Convolutional Network", "y": "fcn", "mt": "すべて畳み込み層で作る", "my": "すべてたたみこみそうでつくる"}, {"id": "0159", "f": "X", "sub": "画像認識", "term": "U-Net", "desc": "縮める側の特徴を、広げる側にスキップ結合でつなぐ U 字の形のセグメンテーションのモデル。医療画像でよく使われる。", "y": "u-net", "mt": "U字の形のセグメンテーション", "my": "uじのかたちのせぐめんてーしょん"}, {"id": "0160", "f": "X", "sub": "画像認識", "term": "SegNet と PSPNet と DeepLab", "desc": "セグメンテーションのモデル。SegNet はエンコーダ・デコーダ型、PSPNet はピラミッドプーリングで大きな文脈をとらえ、DeepLab は Atrous Convolution を使う。", "y": "segnetとpspnetとdeeplab", "mt": "セグメンテーションのモデル", "my": "せぐめんてーしょんのもでる"}, {"id": "0161", "f": "X", "sub": "画像認識", "term": "Mask R-CNN", "desc": "Faster R-CNN に、物体ごとの範囲（マスク）を予測する部分を足した、インスタンスセグメンテーションのモデル。", "y": "maskr-cnn", "mt": "物体ごとのマスクも予測", "my": "ぶったいごとのますくもよそく"}, {"id": "0162", "f": "X", "sub": "画像認識", "term": "OpenPose", "desc": "画像の中の複数の人の、関節の位置と体の姿勢を推定する（姿勢推定）モデル。", "y": "openpose", "mt": "関節の位置と姿勢を推定", "my": "かんせつのいちとしせいをすいてい"}, {"id": "0163", "f": "X", "sub": "自然言語処理", "term": "形態素解析", "desc": "文章を、意味を持つ最小の単位（形態素）に分け、品詞などを決める処理。", "y": "けいたいそかいせき", "mt": "最小の単位に分けて品詞を決める", "my": "さいしょうのたんいにわけてひんしをきめる"}, {"id": "0164", "f": "X", "sub": "自然言語処理", "term": "構文解析", "desc": "文の中の単語どうしの関係（文の構造）を明らかにする処理。", "y": "こうぶんかいせき", "mt": "単語どうしの関係を明らかに", "my": "たんごどうしのかんけいをあきらかに"}, {"id": "0165", "f": "X", "sub": "自然言語処理", "term": "BoW（Bag-of-Words）", "desc": "文章を、単語の順番を無視して、どの単語が何回出たかで表す方法。", "abbr": "Bag-of-Words", "y": "bow", "mt": "単語が何回出たかで表す", "my": "たんごがなんかいでたかであらわす"}, {"id": "0166", "f": "X", "sub": "自然言語処理", "term": "TF-IDF", "desc": "単語の出てくる回数（TF）と、ほかの文書にどれだけ出ないか（IDF）を掛けて、その文書での単語の重要度を表す方法。", "y": "tf-idf", "mt": "回数とめずらしさを掛ける", "my": "かいすうとめずらしさをかける"}, {"id": "0167", "f": "X", "sub": "自然言語処理", "term": "n-gram", "desc": "文章を、となり合う n 個の単語（または文字）の組で区切ったもの。", "y": "n-gram", "mt": "となり合うn個の組で区切る", "my": "となりあうnこのくみでくぎる"}, {"id": "0168", "f": "X", "sub": "自然言語処理", "term": "ワンホットベクトル", "desc": "単語を、その単語の位置だけが 1、ほかが 0 のベクトルで表す方法。単語どうしの意味の近さは表せない。", "y": "わんほっとべくとる", "mt": "その位置だけが1のベクトル", "my": "そのいちだけが1のべくとる"}, {"id": "0169", "f": "X", "sub": "自然言語処理", "term": "分散表現（単語埋め込み）", "desc": "単語を、意味の近いものほど近くなる、少ない次元のベクトルで表す方法。", "y": "ぶんさんひょうげん", "mt": "意味が近いと近いベクトル", "my": "いみがちかいとちかいべくとる"}, {"id": "0170", "f": "X", "sub": "自然言語処理", "term": "word2vec", "desc": "単語の分散表現を学ぶ方法。周りの単語から中心の単語を当てる CBOW と、中心の単語から周りを当てるスキップグラムがある。", "y": "word2vec", "mt": "単語の分散表現を学ぶ", "my": "たんごのぶんさんひょうげんをまなぶ"}, {"id": "0171", "f": "X", "sub": "自然言語処理", "term": "fastText", "desc": "単語をさらに細かい文字の組に分けて学ぶ、word2vec を発展させた方法。知らない単語にも対応しやすい。", "y": "fasttext", "mt": "文字の組に分けて学ぶ", "my": "もじのくみにわけてまなぶ"}, {"id": "0172", "f": "X", "sub": "自然言語処理", "term": "ELMo", "desc": "双方向の LSTM で、文脈によって変わる単語の表現を学ぶモデル。", "y": "elmo", "mt": "文脈で変わる単語の表現", "my": "ぶんみゃくでかわるたんごのひょうげん"}, {"id": "0173", "f": "X", "sub": "自然言語処理", "term": "BERT", "desc": "Transformer のエンコーダを使い、文の前後の両方の文脈から学ぶ言語モデル。隠した単語を当てる学習などで事前学習する。", "y": "bert", "mt": "前後の文脈から学ぶモデル", "my": "ぜんごのぶんみゃくからまなぶもでる"}, {"id": "0174", "f": "X", "sub": "自然言語処理", "term": "GLUE", "desc": "いろいろな言語理解のタスクで、モデルの性能を比べるためのベンチマーク。", "y": "glue", "mt": "言語理解の性能を比べる", "my": "げんごりかいのせいのうをくらべる"}, {"id": "0175", "f": "X", "sub": "自然言語処理", "term": "大規模言語モデル（LLM）", "desc": "大量の文章で事前学習した、大規模な言語モデル。文章の生成・要約・翻訳・質問応答などができる。PaLM などがある。", "abbr": "Large Language Model", "y": "だいきぼげんごもでる", "mt": "大量の文章で学んだ言語モデル", "my": "たいりょうのぶんしょうでまなんだげんごもでる"}, {"id": "0176", "f": "X", "sub": "自然言語処理", "term": "感情分析", "desc": "文章から、よい・悪いなどの感情や評価を読み取るタスク。", "y": "かんじょうぶんせき", "mt": "文章から感情を読み取る", "my": "ぶんしょうからかんじょうをよみとる"}, {"id": "0177", "f": "X", "sub": "音声処理", "term": "A-D変換", "desc": "音などのアナログ信号を、コンピュータが扱えるデジタルの値に変えること。代表的な方式がパルス符号変調（PCM）。", "y": "a-dへんかん", "mt": "アナログをデジタルに変える", "my": "あなろぐをでじたるにかえる"}, {"id": "0178", "f": "X", "sub": "音声処理", "term": "高速フーリエ変換（FFT）", "desc": "音などの波を、どの周波数の成分がどれだけ含まれるか（周波数スペクトル）に、速く分解する計算。", "abbr": "Fast Fourier Transform", "y": "こうそくふーりえへんかん", "mt": "波を周波数の成分に分解", "my": "なみをしゅうはすうのせいぶんにぶんかい"}, {"id": "0179", "f": "X", "sub": "音声処理", "term": "メル尺度", "desc": "人の耳が感じる音の高さに合わせた尺度。低い音の違いには敏感で、高い音の違いには鈍いことを反映する。", "y": "めるしゃくど", "mt": "耳が感じる音の高さの尺度", "my": "みみがかんじるおとのたかさのしゃくど"}, {"id": "0180", "f": "X", "sub": "音声処理", "term": "メル周波数ケプストラム係数（MFCC）", "desc": "メル尺度を使って、声の特徴（スペクトル包絡）を表す数の組。音声認識でよく使われた。", "abbr": "Mel-Frequency Cepstral Coefficients", "y": "めるしゅうはすうけぷすとらむけいすう", "mt": "声の特徴を表す数の組", "my": "こえのとくちょうをあらわすかずのくみ"}, {"id": "0181", "f": "X", "sub": "音声処理", "term": "フォルマント", "desc": "声の周波数スペクトルに現れる、いくつかのピーク。母音の聞き分けに関係する。その周波数がフォルマント周波数。", "y": "ふぉるまんと", "mt": "声のスペクトルのピーク", "my": "こえのすぺくとるのぴーく"}, {"id": "0182", "f": "X", "sub": "音声処理", "term": "音素", "desc": "言葉の意味を区別する、音の最小の単位。", "y": "おんそ", "mt": "意味を区別する音の最小単位", "my": "いみをくべつするおとのさいしょうたんい"}, {"id": "0183", "f": "X", "sub": "音声処理", "term": "隠れマルコフモデル", "desc": "外から見えない状態が確率的に移り変わるモデル。ディープラーニングの前は、音声認識の中心だった。", "y": "かくれまるこふもでる", "mt": "見えない状態が移り変わる", "my": "みえないじょうたいがうつりかわる"}, {"id": "0184", "f": "X", "sub": "音声処理", "term": "WaveNet", "desc": "DeepMind が作った、音声の波形を直接生成するモデル。自然な音声合成を可能にした。", "y": "wavenet", "mt": "音声の波形を直接生成", "my": "おんせいのはけいをちょくせつせいせい"}, {"id": "0185", "f": "X", "sub": "音声処理", "term": "CTC", "desc": "音声と文字のように、入力と出力の長さが違う系列を、位置を合わせずに学習できる方法。音声認識で使う。", "abbr": "Connectionist Temporal Classification", "y": "ctc", "mt": "長さが違う系列を学習", "my": "ながさがちがうけいれつをがくしゅう"}, {"id": "0186", "f": "X", "sub": "音声処理", "term": "話者識別", "desc": "声から、だれが話しているかを見分けるタスク。", "y": "わしゃしきべつ", "mt": "だれが話しているかを見分ける", "my": "だれがはなしているかをみわける"}, {"id": "0187", "f": "X", "sub": "深層強化学習", "term": "DQN", "desc": "Q学習の行動価値を、ディープラーニングで近似する方法。経験を貯めて使い直す工夫などで、ゲームを人間並みにこなした。", "abbr": "Deep Q-Network", "y": "dqn", "mt": "Q学習を深層学習で近似", "my": "qがくしゅうをしんそうがくしゅうできんじ"}, {"id": "0188", "f": "X", "sub": "深層強化学習", "term": "ダブルDQN と デュエリングネットワーク", "desc": "DQN の改良版。ダブルDQN は行動価値の過大評価を抑え、デュエリングネットワークは状態の価値と行動の差を分けて学ぶ。", "y": "だぶるdqnとでゅえりんぐねっとわーく", "mt": "DQNの改良版", "my": "dqnのかいりょうばん"}, {"id": "0189", "f": "X", "sub": "深層強化学習", "term": "Rainbow", "desc": "ダブルDQN やデュエリングネットワーク、ノイジーネットワークなど、DQN の複数の改良を組み合わせた方法。", "y": "rainbow", "mt": "DQNの改良を組み合わせる", "my": "dqnのかいりょうをくみあわせる"}, {"id": "0190", "f": "X", "sub": "深層強化学習", "term": "A3C", "desc": "複数のエージェントが並列に、非同期で学習する Actor-Critic の方法。", "abbr": "Asynchronous Advantage Actor-Critic", "y": "a3c", "mt": "並列に非同期で学ぶ", "my": "へいれつにひどうきでまなぶ"}, {"id": "0191", "f": "X", "sub": "深層強化学習", "term": "APE-X", "desc": "多数のエージェントで集めた経験を、優先度をつけて学習に使う、分散型の深層強化学習。", "y": "ape-x", "mt": "経験に優先度をつける分散型", "my": "けいけんにゆうせんどをつけるぶんさんがた"}, {"id": "0192", "f": "X", "sub": "深層強化学習", "term": "Agent57", "desc": "DeepMind が作った、Atari の57のゲームすべてで、人間の基準を上回った深層強化学習のエージェント。", "y": "agent57", "mt": "57のゲームで人間を上回る", "my": "57のげーむでにんげんをうわまわる"}, {"id": "0193", "f": "X", "sub": "深層強化学習", "term": "AlphaStar と OpenAI Five", "desc": "対戦型のゲームで、トップレベルの人間に勝った深層強化学習の AI。AlphaStar は StarCraft II、OpenAI Five は Dota 2。", "y": "alphastarとopenaifive", "mt": "対戦ゲームで人間に勝ったAI", "my": "たいせんげーむでにんげんにかったai"}, {"id": "0194", "f": "X", "sub": "深層強化学習", "term": "PPO", "desc": "方策を一度に大きく変えすぎないように制限しながら学習する、安定した強化学習の方法。", "abbr": "Proximal Policy Optimization", "y": "ppo", "mt": "方策を大きく変えすぎない", "my": "ほうさくをおおきくかえすぎない"}, {"id": "0195", "f": "X", "sub": "深層強化学習", "term": "sim2real", "desc": "シミュレーションの中で学習したことを、現実のロボットなどに移すこと。", "y": "sim2real", "mt": "シミュレーションを現実に移す", "my": "しみゅれーしょんをげんじつにうつす"}, {"id": "0196", "f": "X", "sub": "深層強化学習", "term": "ドメインランダマイゼーション", "desc": "シミュレーションの環境（色・明るさ・摩擦など）をランダムに変えて学習させ、現実でも通用するようにする方法。", "y": "どめいんらんだまいぜーしょん", "mt": "環境をランダムに変えて学ぶ", "my": "かんきょうをらんだむにかえてまなぶ"}, {"id": "0197", "f": "X", "sub": "深層強化学習", "term": "報酬成形", "desc": "目的を達成しやすいように、途中の行動にも報酬を与えるなど、報酬の設計を工夫すること。", "y": "ほうしゅうせいけい", "mt": "途中の行動にも報酬を与える", "my": "とちゅうのこうどうにもほうしゅうをあたえる"}, {"id": "0198", "f": "X", "sub": "深層強化学習", "term": "オフライン強化学習", "desc": "環境とやり取りせずに、すでに集めたデータだけで方策を学ぶ強化学習。", "y": "おふらいんきょうかがくしゅう", "mt": "集めたデータだけで学ぶ", "my": "あつめたでーただけでまなぶ"}, {"id": "0199", "f": "X", "sub": "深層強化学習", "term": "マルチエージェント強化学習（MARL）", "desc": "複数のエージェントが、同じ環境で協力したり競争したりしながら学ぶ強化学習。", "abbr": "Multi-Agent Reinforcement Learning", "y": "まるちえーじぇんときょうかがくしゅう", "mt": "複数のエージェントで学ぶ", "my": "ふくすうのえーじぇんとでまなぶ"}, {"id": "0200", "f": "X", "sub": "データ生成", "term": "GAN（敵対的生成ネットワーク）", "desc": "データを作る生成器と、本物か偽物かを見分ける識別器を競わせて学ぶ生成モデル。", "abbr": "Generative Adversarial Network", "y": "gan", "mt": "生成器と識別器を競わせる", "my": "せいせいきとしきべつきをきそわせる"}, {"id": "0201", "f": "X", "sub": "データ生成", "term": "DCGAN", "desc": "生成器と識別器に畳み込みニューラルネットワークを使った GAN。", "abbr": "Deep Convolutional GAN", "y": "dcgan", "mt": "畳み込みを使ったGAN", "my": "たたみこみをつかったgan"}, {"id": "0202", "f": "X", "sub": "データ生成", "term": "Pix2Pix", "desc": "対になった画像（線画と写真など）を使って、画像を別の画像に変換する GAN。", "y": "pix2pix", "mt": "対の画像で画像を変換", "my": "ついのがぞうでがぞうをへんかん"}, {"id": "0203", "f": "X", "sub": "データ生成", "term": "CycleGAN", "desc": "対になっていない画像の集まり（馬とシマウマなど）から、画像の変換を学ぶ GAN。", "y": "cyclegan", "mt": "対でない画像から変換を学ぶ", "my": "ついでないがぞうからへんかんをまなぶ"}, {"id": "0204", "f": "X", "sub": "データ生成", "term": "拡散モデル（Diffusion Model）", "desc": "データに少しずつノイズを加える過程と、ノイズを取り除いて戻す過程を学び、ノイズから画像などを生成するモデル。", "y": "かくさんもでる", "mt": "ノイズを取り除いて生成する", "my": "のいずをとりのぞいてせいせいする"}, {"id": "0205", "f": "X", "sub": "データ生成", "term": "NeRF", "desc": "いくつかの方向から撮った写真から、3次元の場面を学んで、別の方向から見た画像を作る方法。", "abbr": "Neural Radiance Fields", "y": "nerf", "mt": "写真から3次元の場面を学ぶ", "my": "しゃしんから3じげんのばめんをまなぶ"}, {"id": "0206", "f": "X", "sub": "転移学習とマルチモーダル", "term": "事前学習済みモデル", "desc": "大量のデータで先に学習しておいたモデル。転移学習やファインチューニングの出発点にする。", "y": "じぜんがくしゅうずみもでる", "mt": "先に学習しておいたモデル", "my": "さきにがくしゅうしておいたもでる"}, {"id": "0207", "f": "X", "sub": "転移学習とマルチモーダル", "term": "自己教師あり学習", "desc": "データの一部を隠して当てさせるなど、正解をデータ自身から作って学ぶ方法。人が正解を付けなくてよい。", "y": "じこきょうしありがくしゅう", "mt": "正解をデータ自身から作る", "my": "せいかいをでーたじしんからつくる"}, {"id": "0208", "f": "X", "sub": "転移学習とマルチモーダル", "term": "Few-shot と One-shot と Zero-shot", "desc": "少ない例（Few-shot）、1つの例（One-shot）、例なし（Zero-shot）で、新しいタスクをこなすこと。", "y": "few-shotとone-shotとzero-shot", "mt": "少ない例や例なしで学ぶ", "my": "すくないれいやれいなしでまなぶ"}, {"id": "0209", "f": "X", "sub": "転移学習とマルチモーダル", "term": "破滅的忘却", "desc": "新しいタスクを学習すると、前に学んだことを大きく忘れてしまう現象。", "y": "はめつてきぼうきゃく", "mt": "前に学んだことを忘れる", "my": "まえにまなんだことをわすれる"}, {"id": "0210", "f": "X", "sub": "転移学習とマルチモーダル", "term": "基盤モデル", "desc": "大量のデータで学習し、いろいろなタスクに使い回せる大きなモデル。", "y": "きばんもでる", "mt": "いろいろなタスクに使い回せる", "my": "いろいろなたすくにつかいまわせる"}, {"id": "0211", "f": "X", "sub": "転移学習とマルチモーダル", "term": "CLIP", "desc": "画像と文章の組を大量に学び、画像と言葉を同じ空間で扱えるようにしたモデル。例なし（Zero-shot）での画像の分類ができる。", "y": "clip", "mt": "画像と言葉を同じ空間で扱う", "my": "がぞうとことばをおなじくうかんであつかう"}, {"id": "0212", "f": "X", "sub": "転移学習とマルチモーダル", "term": "Text-To-Image", "desc": "文章から画像を生成するタスク。DALL-E などのモデルがある。", "y": "text-to-image", "mt": "文章から画像を生成", "my": "ぶんしょうからがぞうをせいせい"}, {"id": "0213", "f": "X", "sub": "転移学習とマルチモーダル", "term": "Image Captioning と Visual Question Answering", "desc": "Image Captioning は画像の説明文を作るタスク。Visual Question Answering は画像についての質問に答えるタスク。", "y": "imagecaptioningとvisualquestionanswering", "mt": "画像の説明と画像への質問応答", "my": "がぞうのせつめいとがぞうへのしつもんおうとう"}, {"id": "0214", "f": "X", "sub": "転移学習とマルチモーダル", "term": "マルチタスク学習", "desc": "1つのモデルで、複数のタスクを同時に学習すること。Unified-IO や Flamingo などのモデルがある。", "y": "まるちたすくがくしゅう", "mt": "複数のタスクを同時に学ぶ", "my": "ふくすうのたすくをどうじにまなぶ"}, {"id": "0215", "f": "X", "sub": "解釈性と軽量化", "term": "説明可能AI（XAI）", "desc": "AI が、なぜその判断をしたのかを、人が理解できるように示す技術や考え方。", "abbr": "Explainable AI", "y": "せつめいかのうai", "mt": "判断の理由を示す", "my": "はんだんのりゆうをしめす"}, {"id": "0216", "f": "X", "sub": "解釈性と軽量化", "term": "CAM と Grad-CAM", "desc": "CNN が画像のどこを見て判断したかを、ヒートマップで示す方法。Grad-CAM は勾配を使い、いろいろな CNN に使える。", "y": "camとgrad-cam", "mt": "どこを見たかをヒートマップで", "my": "どこをみたかをひーとまっぷで"}, {"id": "0217", "f": "X", "sub": "解釈性と軽量化", "term": "LIME", "desc": "1つの予測の周りで、単純なモデルで近似して、どの特徴が判断に効いたかを説明する方法。", "y": "lime", "mt": "単純なモデルで近似して説明", "my": "たんじゅんなもでるできんじしてせつめい"}, {"id": "0218", "f": "X", "sub": "解釈性と軽量化", "term": "SHAP", "desc": "ゲーム理論のシャープレイ値を使って、それぞれの特徴が予測にどれだけ貢献したかを示す方法。", "y": "shap", "mt": "シャープレイ値で貢献を示す", "my": "しゃーぷれいちでこうけんをしめす"}, {"id": "0219", "f": "X", "sub": "解釈性と軽量化", "term": "Permutation Importance", "desc": "ある特徴の値をばらばらに入れ替えたときに、性能がどれだけ下がるかで、その特徴の重要度を測る方法。", "y": "permutationimportance", "mt": "入れ替えて重要度を測る", "my": "いれかえてじゅうようどをはかる"}, {"id": "0220", "f": "X", "sub": "解釈性と軽量化", "term": "蒸留", "desc": "大きなモデル（教師）の出力をまねるように、小さなモデル（生徒）を学習させて、モデルを軽くする方法。", "y": "じょうりゅう", "mt": "大きなモデルをまねて軽くする", "my": "おおきなもでるをまねてかるくする"}, {"id": "0221", "f": "X", "sub": "解釈性と軽量化", "term": "プルーニング", "desc": "重要度の低い重みやニューロンを取り除いて、モデルを軽くする方法（枝刈り）。", "y": "ぷるーにんぐ", "mt": "重要でない重みを取り除く", "my": "じゅうようでないおもみをとりのぞく"}, {"id": "0222", "f": "X", "sub": "解釈性と軽量化", "term": "量子化", "desc": "重みなどの数を、少ないビット数で表して、モデルを軽く・速くする方法。", "y": "りょうしか", "mt": "少ないビット数で表す", "my": "すくないびっとすうであらわす"}, {"id": "0223", "f": "X", "sub": "解釈性と軽量化", "term": "宝くじ仮説", "desc": "大きなネットワークの中には、単独で学習しても同じくらいの性能が出る、小さなネットワーク（当たりくじ）がふくまれているという仮説。", "y": "たからくじかせつ", "mt": "中に小さな当たりの網がある", "my": "なかにちいさなあたりのあみがある"}, {"id": "0224", "f": "X", "sub": "解釈性と軽量化", "term": "エッジAI", "desc": "クラウドではなく、スマホやカメラなどの機器（エッジ）の上で AI を動かすこと。速く応え、データを外に出さずに済む。", "y": "えっじai", "mt": "機器の上でAIを動かす", "my": "ききのうえでaiをうごかす"}, {"id": "0225", "f": "S", "sub": "AIプロジェクト", "term": "CRISP-DM", "desc": "データ分析のプロジェクトの進め方の標準。ビジネスの理解・データの理解・データの準備・モデリング・評価・展開の流れ。機械学習向けに発展させたものが CRISP-ML。", "abbr": "Cross-Industry Standard Process for Data Mining", "y": "crisp-dm", "mt": "データ分析の進め方の標準", "my": "でーたぶんせきのすすめかたのひょうじゅん"}, {"id": "0226", "f": "S", "sub": "AIプロジェクト", "term": "PoC", "desc": "概念実証。本格的に作る前に、AI で本当に効果が出るかを小さく試して確かめること。", "abbr": "Proof of Concept", "y": "poc", "mt": "小さく試して確かめる", "my": "ちいさくためしてたしかめる"}, {"id": "0227", "f": "S", "sub": "AIプロジェクト", "term": "MLOps", "desc": "機械学習のモデルを、開発から運用・監視・改善まで、継続して回していくための考え方と仕組み。", "y": "mlops", "mt": "開発から運用まで回し続ける", "my": "かいはつからうんようまでまわしつづける"}, {"id": "0228", "f": "S", "sub": "AIプロジェクト", "term": "BPR", "desc": "業務の流れを根本から見直して作り直すこと。AI の導入にあわせて行うことがある。", "abbr": "Business Process Re-engineering", "y": "bpr", "mt": "業務を根本から作り直す", "my": "ぎょうむをこんぽんからつくりなおす"}, {"id": "0229", "f": "S", "sub": "AIプロジェクト", "term": "アジャイルとウォーターフォール", "desc": "開発の進め方。アジャイルは小さく作って直すのをくり返す。ウォーターフォールは決めた工程を順番に進める。AI の開発はアジャイルが向くことが多い。", "y": "あじゃいるとうぉーたーふぉーる", "mt": "くり返すか工程を順に進むか", "my": "くりかえすかこうていをじゅんにすすむか"}, {"id": "0230", "f": "S", "sub": "AIプロジェクト", "term": "Docker と Jupyter Notebook", "desc": "AI の開発でよく使う道具。Docker はアプリと動く環境をまとめて動かす仕組み。Jupyter Notebook はプログラムと結果を並べて試せる環境。", "y": "dockerとjupyternotebook", "mt": "AIの開発でよく使う道具", "my": "aiのかいはつでよくつかうどうぐ"}, {"id": "0231", "f": "S", "sub": "AIプロジェクト", "term": "Web API", "desc": "インターネットを通して、ほかのプログラムの機能を呼び出す窓口。学習済みモデルを公開して使ってもらうときに使う。", "y": "webapi", "mt": "ほかのプログラムの機能を呼ぶ窓口", "my": "ほかのぷろぐらむのきのうをよぶまどぐち"}, {"id": "0232", "f": "S", "sub": "AIプロジェクト", "term": "アノテーション", "desc": "学習データに、正解のラベルや情報を付ける作業。", "y": "あのてーしょん", "mt": "正解のラベルを付ける作業", "my": "せいかいのらべるをつけるさぎょう"}, {"id": "0233", "f": "S", "sub": "AIプロジェクト", "term": "データリーケージ", "desc": "本当は予測のときに使えない情報（テストや未来の情報など）が学習に混ざり、評価が実際より良く見えてしまうこと。", "y": "でーたりーけーじ", "mt": "使えない情報が学習に混ざる", "my": "つかえないじょうほうががくしゅうにまざる"}, {"id": "0234", "f": "S", "sub": "AIプロジェクト", "term": "コーパスとオープンデータセット", "desc": "コーパスは、言語の研究や学習のために集めた大量の文章のデータ。オープンデータセットは、だれでも使えるように公開されたデータの集まり。", "y": "こーぱすとおーぷんでーたせっと", "mt": "集めた文章と公開されたデータ", "my": "あつめたぶんしょうとこうかいされたでーた"}, {"id": "0235", "f": "S", "sub": "数理・統計", "term": "平均と中央値と最頻値", "desc": "データの代表の値。平均は合計を個数で割った値、中央値は大きさの順で真ん中の値、最頻値は最も多く出る値。", "y": "へいきんとちゅうおうちとさいひんち", "mt": "データの代表の値", "my": "でーたのだいひょうのあたい"}, {"id": "0236", "f": "S", "sub": "数理・統計", "term": "分散と標準偏差", "desc": "データのばらつきを表す値。分散は平均からの差の2乗の平均、標準偏差はその平方根。", "y": "ぶんさんとひょうじゅんへんさ", "mt": "データのばらつきを表す", "my": "でーたのばらつきをあらわす"}, {"id": "0237", "f": "S", "sub": "数理・統計", "term": "相関係数", "desc": "2つの値の直線的な関係の強さを、−1〜1 で表した値。", "y": "そうかんけいすう", "mt": "直線的な関係の強さ", "my": "ちょくせんてきなかんけいのつよさ"}, {"id": "0238", "f": "S", "sub": "数理・統計", "term": "疑似相関", "desc": "2つの値に関係がないのに、第3の要因のせいで、相関があるように見えること。", "y": "ぎじそうかん", "mt": "第3の要因で相関に見える", "my": "だい3のよういんでそうかんにみえる"}, {"id": "0239", "f": "S", "sub": "数理・統計", "term": "偏相関係数", "desc": "ほかの値の影響を取り除いたうえでの、2つの値の相関係数。", "y": "へんそうかんけいすう", "mt": "ほかの影響を除いた相関", "my": "ほかのえいきょうをのぞいたそうかん"}, {"id": "0240", "f": "S", "sub": "数理・統計", "term": "共分散", "desc": "2つの値が、一緒にどう変わるかを表す値。正なら一緒に増え、負なら一方が増えると他方が減る。", "y": "きょうぶんさん", "mt": "2つの値が一緒にどう変わるか", "my": "2つのあたいがいっしょにどうかわるか"}, {"id": "0241", "f": "S", "sub": "数理・統計", "term": "正規分布", "desc": "平均を中心に左右対称の、つりがね形の確率分布。", "y": "せいきぶんぷ", "mt": "左右対称のつりがね形", "my": "さゆうたいしょうのつりがねがた"}, {"id": "0242", "f": "S", "sub": "数理・統計", "term": "ベルヌーイ分布と二項分布", "desc": "ベルヌーイ分布は、成功か失敗かの1回の試行の分布。二項分布は、それを n 回くり返したときの成功の回数の分布。", "y": "べるぬーいぶんぷとにこうぶんぷ", "mt": "1回の試行とn回くり返す分布", "my": "1かいのしこうとnかいくりかえすぶんぷ"}, {"id": "0243", "f": "S", "sub": "数理・統計", "term": "ポアソン分布", "desc": "一定の時間や範囲の中で、まれな出来事が何回起きるかを表す確率分布。", "y": "ぽあそんぶんぷ", "mt": "まれな出来事の回数の分布", "my": "まれなできごとのかいすうのぶんぷ"}, {"id": "0244", "f": "S", "sub": "数理・統計", "term": "期待値", "desc": "確率で重みを付けた平均。何度もくり返したときに平均として期待できる値。", "y": "きたいち", "mt": "確率で重みを付けた平均", "my": "かくりつでおもみをつけたへいきん"}, {"id": "0245", "f": "S", "sub": "数理・統計", "term": "条件付き確率", "desc": "ある出来事が起きたという条件のもとで、別の出来事が起きる確率。", "y": "じょうけんつきかくりつ", "mt": "ある条件のもとでの確率", "my": "あるじょうけんのもとでのかくりつ"}, {"id": "0246", "f": "S", "sub": "数理・統計", "term": "最小二乗法", "desc": "予測と実際の値の差の2乗の合計が最も小さくなるように、式の係数を決める方法。", "y": "さいしょうにじょうほう", "mt": "差の2乗の合計を最小に", "my": "さの2じょうのごうけいをさいしょうに"}, {"id": "0247", "f": "S", "sub": "数理・統計", "term": "最尤法", "desc": "観測されたデータが得られる確率（尤度）が最も大きくなるように、モデルのパラメータを決める方法。", "y": "さいゆうほう", "mt": "尤度が最大になるように決める", "my": "ゆうどがさいだいになるようにきめる"}, {"id": "0248", "f": "S", "sub": "数理・統計", "term": "帰無仮説と対立仮説", "desc": "仮説検定の考え方。「差がない」とする帰無仮説を立て、それが否定されたら「差がある」とする対立仮説を採る。", "y": "きむかせつとたいりつかせつ", "mt": "差がないと差があるの仮説", "my": "さがないとさがあるのかせつ"}, {"id": "0249", "f": "S", "sub": "数理・統計", "term": "ユークリッド距離とマハラノビス距離", "desc": "ユークリッド距離は、ふつうのまっすぐな距離。マハラノビス距離は、データのばらつきや相関を考えに入れた距離。", "y": "ゆーくりっどきょりとまはらのびすきょり", "mt": "まっすぐな距離とばらつきを考えた距離", "my": "まっすぐなきょりとばらつきをかんがえたきょり"}, {"id": "0250", "f": "S", "sub": "数理・統計", "term": "コサイン類似度", "desc": "2つのベクトルの向きがどれだけ近いかを、−1〜1 で表した値。文章の似ている度合いなどに使う。", "y": "こさいんるいじど", "mt": "ベクトルの向きの近さ", "my": "べくとるのむきのちかさ"}, {"id": "0251", "f": "S", "sub": "数理・統計", "term": "相互情報量", "desc": "2つの変数の一方を知ると、もう一方についてどれだけわかるかを表す量。", "y": "そうごじょうほうりょう", "mt": "一方でもう一方がどれだけわかるか", "my": "いっぽうでもういっぽうがどれだけわかるか"}, {"id": "0252", "f": "S", "sub": "数理・統計", "term": "移動平均", "desc": "時系列のデータで、決めた期間の平均を、ずらしながら求めたもの。細かい変動をならして傾向を見る。", "y": "いどうへいきん", "mt": "期間の平均をずらして求める", "my": "きかんのへいきんをずらしてもとめる"}, {"id": "0253", "f": "S", "sub": "数理・統計", "term": "外れ値", "desc": "ほかのデータから大きく離れた値。分析の結果を大きく左右するので、扱いに注意する。", "y": "はずれち", "mt": "ほかから大きく離れた値", "my": "ほかからおおきくはなれたあたい"}, {"id": "0254", "f": "L", "sub": "法律と契約", "term": "個人情報", "desc": "生きている個人に関する情報で、名前や生年月日など、特定の個人を識別できるもの。個人識別符号（指紋のデータ、マイナンバーなど）を含むものも個人情報。", "y": "こじんじょうほう", "mt": "特定の個人を識別できる情報", "my": "とくていのこじんをしきべつできるじょうほう"}, {"id": "0255", "f": "L", "sub": "法律と契約", "term": "要配慮個人情報", "desc": "人種・信条・病歴・犯罪の経歴など、差別や偏見につながらないよう特に配慮が必要な個人情報。取得には原則として本人の同意が要る。", "y": "ようはいりょこじんじょうほう", "mt": "特に配慮が必要な個人情報", "my": "とくにはいりょがひつようなこじんじょうほう"}, {"id": "0256", "f": "L", "sub": "法律と契約", "term": "個人データと保有個人データ", "desc": "個人データは、データベースなどで検索できるように整理された個人情報。保有個人データは、事業者が開示や訂正などの権限を持つ個人データ。", "y": "こじんでーたとほゆうこじんでーた", "mt": "整理された個人情報と開示に応じるもの", "my": "せいりされたこじんじょうほうとかいじにおうじるもの"}, {"id": "0257", "f": "L", "sub": "法律と契約", "term": "第三者提供と委託", "desc": "第三者提供は、個人データをほかの事業者などに渡すことで、原則として本人の同意が要る。委託（業務の外注など）で渡す場合は、第三者提供にあたらない。", "y": "だいさんしゃていきょうといたく", "mt": "ほかに渡すことと任せること", "my": "ほかにわたすこととまかせること"}, {"id": "0258", "f": "L", "sub": "法律と契約", "term": "匿名加工情報と仮名加工情報", "desc": "匿名加工情報は、特定の個人を識別できず元にも戻せないように加工した情報。仮名加工情報は、ほかの情報と照らし合わせなければ識別できないように加工した情報で、主に社内の分析に使う。", "y": "とくめいかこうじょうほうとかめいかこうじょうほう", "mt": "元に戻せない加工と照合で識別できる加工", "my": "もとにもどせないかこうとしょうごうでしきべつできるかこう"}, {"id": "0259", "f": "L", "sub": "法律と契約", "term": "GDPR", "desc": "EU の一般データ保護規則。EU の中の人の個人データを扱うなら、EU の外の事業者にも適用されることがある。", "abbr": "General Data Protection Regulation", "y": "gdpr", "mt": "EUの一般データ保護規則", "my": "euのいっぱんでーたほごきそく"}, {"id": "0260", "f": "L", "sub": "法律と契約", "term": "著作物と創作性", "desc": "著作物は、思想や感情を創作的に表現したもの。ありふれた表現や単なるデータには、創作性がなく著作物にならない。", "y": "ちょさくぶつとそうさくせい", "mt": "思想や感情の創作的な表現", "my": "しそうやかんじょうのそうさくてきなひょうげん"}, {"id": "0261", "f": "L", "sub": "法律と契約", "term": "著作権法第30条の4", "desc": "AI の学習（情報解析）のように、作品の表現を味わう目的ではない利用は、原則として著作権者の許諾なくできるという規定。著作権者の利益を不当に害する場合は除く。", "y": "ちょさくけんほうだい30じょうの4", "mt": "AIの学習は原則許諾なし", "my": "aiのがくしゅうはげんそくきょだくなし"}, {"id": "0262", "f": "L", "sub": "法律と契約", "term": "AI生成物と著作権", "desc": "AI が作ったものは、人が創作の意図を持ち、創作的に関わった場合に、著作物になりうる。既存の作品と似ていて（類似性）、それをもとにしていれば（依拠性）、著作権の侵害になりうる。", "y": "aiせいせいぶつとちょさくけん", "mt": "人が創作的に関われば著作物", "my": "ひとがそうさくてきにかかわればちょさくぶつ"}, {"id": "0263", "f": "L", "sub": "法律と契約", "term": "特許権", "desc": "発明を守る権利。特許を受けるには、新しいこと（新規性）や、簡単に思いつけないこと（進歩性）などが必要。", "y": "とっきょけん", "mt": "発明を守る権利", "my": "はつめいをまもるけんり"}, {"id": "0264", "f": "L", "sub": "法律と契約", "term": "職務発明", "desc": "従業者が、会社の仕事として行った発明。契約や規則で決めておけば、特許を受ける権利を会社のものにできる（従業者には相当の利益を与える）。", "y": "しょくむはつめい", "mt": "会社の仕事として行った発明", "my": "かいしゃのしごととしておこなったはつめい"}, {"id": "0265", "f": "L", "sub": "法律と契約", "term": "営業秘密", "desc": "不正競争防止法で守られる秘密の情報。秘密として管理されている（秘密管理性）、役に立つ（有用性）、知られていない（非公知性）の3つの条件が必要。", "y": "えいぎょうひみつ", "mt": "法律で守られる秘密の情報", "my": "ほうりつでまもられるひみつのじょうほう"}, {"id": "0266", "f": "L", "sub": "法律と契約", "term": "限定提供データ", "desc": "決まった相手に提供するために、電子的に管理して集めたデータ。営業秘密にあたらなくても、不正競争防止法で守られる。", "y": "げんていていきょうでーた", "mt": "決まった相手に提供するデータ", "my": "きまったあいてにていきょうするでーた"}, {"id": "0267", "f": "L", "sub": "法律と契約", "term": "独占禁止法と AI", "desc": "AI やデータを使った価格の調整、データの囲い込みなどが、公正な競争をさまたげないか（公正競争阻害性）が論点になっている。", "y": "どくせんきんしほうとai", "mt": "公正な競争をさまたげないか", "my": "こうせいなきょうそうをさまたげないか"}, {"id": "0268", "f": "L", "sub": "法律と契約", "term": "AI・データの利用に関する契約ガイドライン", "desc": "経済産業省が作った、AI の開発やデータの利用の契約の考え方をまとめたもの。開発をアセスメント・PoC・開発・追加学習の段階に分けて考える。", "y": "aiでーたのりようにかんするけいやくがいどらいん", "mt": "AIとデータの契約の考え方", "my": "aiとでーたのけいやくのかんがえかた"}, {"id": "0269", "f": "L", "sub": "法律と契約", "term": "請負契約と準委任契約", "desc": "請負契約は、仕事の完成を約束する契約。準委任契約は、作業をていねいに行うことを約束し、完成は約束しない契約。結果が読みにくい AI の開発では、準委任が使われることが多い。", "y": "うけおいけいやくとじゅんいにんけいやく", "mt": "完成を約束するか作業を約束するか", "my": "かんせいをやくそくするかさぎょうをやくそくするか"}, {"id": "0270", "f": "L", "sub": "法律と契約", "term": "精度保証", "desc": "AI の精度を契約で約束すること。AI はデータによって結果が変わるため、事前に精度を保証するのは難しい。", "y": "せいどほしょう", "mt": "精度を契約で約束する", "my": "せいどをけいやくでやくそくする"}, {"id": "0271", "f": "L", "sub": "法律と契約", "term": "SaaS と利用規約", "desc": "SaaS は、インターネットを通してソフトを使うサービス。AI のサービスでは、利用規約で、入力したデータの使われ方や生成物の扱いを確かめる。", "y": "saasとりようきやく", "mt": "ネットで使うソフトと使う決まり", "my": "ねっとでつかうそふととつかうきまり"}, {"id": "0272", "f": "L", "sub": "倫理とガバナンス", "term": "ハードローとソフトロー", "desc": "ハードローは、法的な強制力のある法律。ソフトローは、強制力はないが守ることが期待される指針やガイドライン。", "y": "はーどろーとそふとろー", "mt": "強制力のある法律とない指針", "my": "きょうせいりょくのあるほうりつとないししん"}, {"id": "0273", "f": "L", "sub": "倫理とガバナンス", "term": "リスクベースアプローチ", "desc": "リスクの大きさに応じて、規制や対策の強さを変える考え方。", "y": "りすくべーすあぷろーち", "mt": "リスクに応じて強さを変える", "my": "りすくにおうじてつよさをかえる"}, {"id": "0274", "f": "L", "sub": "倫理とガバナンス", "term": "プライバシー・バイ・デザイン", "desc": "システムを企画・設計する最初の段階から、プライバシーの保護を組み込んでおく考え方。", "y": "ぷらいばしーばいでざいん", "mt": "最初からプライバシーを組み込む", "my": "さいしょからぷらいばしーをくみこむ"}, {"id": "0275", "f": "L", "sub": "倫理とガバナンス", "term": "カメラ画像利活用ガイドブック", "desc": "カメラの画像を商業目的で使うときに、プライバシーの面で配慮すべきことをまとめた手引き。", "y": "かめらがぞうりかつようがいどぶっく", "mt": "カメラの画像を使うときの手引き", "my": "かめらのがぞうをつかうときのてびき"}, {"id": "0276", "f": "L", "sub": "倫理とガバナンス", "term": "アルゴリズムバイアス", "desc": "学習データの偏りなどによって、AI の判断が特定の人々に不公平になること。", "y": "あるごりずむばいあす", "mt": "判断が特定の人に不公平になる", "my": "はんだんがとくていのひとにふこうへいになる"}, {"id": "0277", "f": "L", "sub": "倫理とガバナンス", "term": "サンプリングバイアス", "desc": "集めたデータが、対象全体の様子を正しく表していない偏り。", "y": "さんぷりんぐばいあす", "mt": "集めたデータが全体を表さない", "my": "あつめたでーたがぜんたいをあらわさない"}, {"id": "0278", "f": "L", "sub": "倫理とガバナンス", "term": "センシティブ属性と代理変数", "desc": "センシティブ属性は、性別や人種など、差別につながりうる属性。代理変数は、それを直接使わなくても、住所などが代わりの手がかりになってしまう変数。", "y": "せんしてぃぶぞくせいとだいりへんすう", "mt": "差別につながる属性と代わりの変数", "my": "さべつにつながるぞくせいとかわりのへんすう"}, {"id": "0279", "f": "L", "sub": "倫理とガバナンス", "term": "Adversarial Examples", "desc": "人には見分けられないわずかなノイズを加えて、AI に誤った判断をさせる入力。これを使う攻撃が Adversarial Attack。", "y": "adversarialexamples", "mt": "わずかなノイズで誤らせる入力", "my": "わずかなのいずであやまらせるにゅうりょく"}, {"id": "0280", "f": "L", "sub": "倫理とガバナンス", "term": "データ汚染とモデル汚染", "desc": "学習データや学習済みモデルに、悪意のあるデータや細工を入れて、AI の動きをおかしくする攻撃。", "y": "でーたおせんともでるおせん", "mt": "悪意のあるデータや細工を入れる", "my": "あくいのあるでーたやさいくをいれる"}, {"id": "0281", "f": "L", "sub": "倫理とガバナンス", "term": "モデル窃取とデータ窃取", "desc": "AI に何度も問い合わせるなどして、モデルの中身や学習に使ったデータを盗み出す攻撃。", "y": "もでるせっしゅとでーたせっしゅ", "mt": "モデルやデータを盗み出す", "my": "もでるやでーたをぬすみだす"}, {"id": "0282", "f": "L", "sub": "倫理とガバナンス", "term": "セキュリティ・バイ・デザイン", "desc": "システムを企画・設計する最初の段階から、セキュリティの対策を組み込んでおく考え方。", "y": "せきゅりてぃばいでざいん", "mt": "最初からセキュリティを組み込む", "my": "さいしょからせきゅりてぃをくみこむ"}, {"id": "0283", "f": "L", "sub": "倫理とガバナンス", "term": "ディープフェイク", "desc": "ディープラーニングで作った、本物の人物の顔や声に似せた偽の動画や音声。なりすましや偽情報に悪用されることがある。", "y": "でぃーぷふぇいく", "mt": "本物に似せた偽の動画や音声", "my": "ほんものににせたにせのどうがやおんせい"}, {"id": "0284", "f": "L", "sub": "倫理とガバナンス", "term": "フェイクニュース", "desc": "事実と違う、うその情報のニュース。AI で大量に、本物らしく作れてしまうことが問題になっている。", "y": "ふぇいくにゅーす", "mt": "うその情報のニュース", "my": "うそのじょうほうのにゅーす"}, {"id": "0285", "f": "L", "sub": "倫理とガバナンス", "term": "説明可能性と透明性", "desc": "AI の判断の理由や、どんなデータで作ったか（データの来歴）を、説明できるようにしておくこと。中身がわからない状態をブラックボックスという。", "y": "せつめいかのうせいととうめいせい", "mt": "判断の理由や来歴を説明できる", "my": "はんだんのりゆうやらいれきをせつめいできる"}, {"id": "0286", "f": "L", "sub": "倫理とガバナンス", "term": "エコーチェンバーとフィルターバブル", "desc": "エコーチェンバーは、似た意見ばかりが響き合って強まる現象。フィルターバブルは、おすすめの仕組みで自分の好む情報ばかりに囲まれること。民主主義への影響が議論されている。", "y": "えこーちぇんばーとふぃるたーばぶる", "mt": "同じ意見や好みの情報ばかりになる", "my": "おなじいけんやこのみのじょうほうばかりになる"}, {"id": "0287", "f": "L", "sub": "倫理とガバナンス", "term": "モデル学習の電力消費", "desc": "大規模なモデルの学習には大量の電力が要り、気候変動など環境への影響が議論されている。", "y": "もでるがくしゅうのでんりょくしょうひ", "mt": "学習に大量の電力が要る", "my": "がくしゅうにたいりょうのでんりょくがいる"}, {"id": "0288", "f": "L", "sub": "倫理とガバナンス", "term": "AIとの協働とスキルの喪失", "desc": "AI が雇用に与える影響の論点。AI と人が役割を分けて協働する一方、仕事を任せすぎると人の技能が失われる心配がある。", "y": "aiとのきょうどうとすきるのそうしつ", "mt": "任せすぎると技能が失われる", "my": "まかせすぎるとぎのうがうしなわれる"}, {"id": "0289", "f": "L", "sub": "倫理とガバナンス", "term": "インクルージョン", "desc": "年齢・障害・言語などにかかわらず、だれもが AI の恩恵を受けられるようにすること。", "y": "いんくるーじょん", "mt": "だれもがAIの恩恵を受ける", "my": "だれもがaiのおんけいをうける"}, {"id": "0290", "f": "L", "sub": "倫理とガバナンス", "term": "AIガバナンス", "desc": "組織が AI を倫理的・安全に使うための管理の仕組み。AI ポリシー、倫理アセスメント、AI に対する監査、モニタリングなど。", "y": "aiがばなんす", "mt": "AIを安全に使う管理の仕組み", "my": "aiをあんぜんにつかうかんりのしくみ"}, {"id": "0291", "f": "L", "sub": "倫理とガバナンス", "term": "倫理アセスメント", "desc": "AI を作る・使う前に、倫理的な問題やリスクがないかを評価すること。", "y": "りんりあせすめんと", "mt": "使う前に倫理の問題を評価", "my": "つかうまえにりんりのもんだいをひょうか"}, {"id": "0292", "f": "L", "sub": "倫理とガバナンス", "term": "人間の関与", "desc": "AI の判断に、人が確認・判断する段階を入れておくこと（ヒューマン・イン・ザ・ループ）。", "y": "にんげんのかんよ", "mt": "人が確認する段階を入れる", "my": "ひとがかくにんするだんかいをいれる"}, {"id": "0293", "f": "L", "sub": "倫理とガバナンス", "term": "再現性とトレーサビリティ", "desc": "再現性は、同じ条件で同じ結果を得られること。トレーサビリティは、データやモデルの変更の履歴を、あとからたどれること。", "y": "さいげんせいととれーさびりてぃ", "mt": "同じ結果を得られ履歴を追える", "my": "おなじけっかをえられりれきをおえる"}];
